INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p860044-math002', 'stk-user5900', 'MATH 002', 'info', '{"desc": "الكتاب ثم الكتاب ثم الكتاب\n\nنصيحة مني أنا أهملت الكتاب وعدت المادة\n\nلأن اسئلة المياجر تعتمد على امثلة الكتاب و اسئلة الكتاب\n\nوفي الكتاب شررح ممتاز عن المادة ويفهمك الاساس و أبدأ في حل اسئلة الأود نمبر وحل اسئلة الرفيو اللي بآخر\n\nكل شابتر مع الأولد اكزامز ولا تنسى الأطلاع على نوته الشرقاوي ونوتة خان لأنها الأفضل في الجامعة\n\nتحياتي لك وبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/help-students-who-study-math002-this-summer/109011/12", "user": "user5900", "ts": 1309171594000, "tid": 109011, "pn": 12}}', 1309171594000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421193-math002', 'stk-user8581', 'MATH 002', 'info', '{"desc": "ما اذكر فيه اولداقزام غير ادهم لماث 002 يمكن اكون غلطان لكن مشكلته فيه شوي اخطاء وبعض الاسئلة محلولة بطريقة غريبة\nعلى العموم في 002 اشوف اسئلة الكتاب والريساتيشن وقبل الميجر اولداقزامات كافي …\nوهذا الموضوع فيه راي الطلاب عن الكورس راح يفيدك\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=125420\nوعلى العموم رح للجمعية يمكن فيه اولداقزامات غير ادهم … + اطلع هالموضوع فيه ملفات كثيرة للماث وبقية المواد\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=139547", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/168574/3", "user": "user8581", "ts": 1421882549000, "tid": 168574, "pn": 3}}', 1421882549000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475464-math002', 'stk-oria27', 'MATH 002', 'info', '{"desc": "162 - math 102\n\nالتحضير : ولا كلاس حضّر فيه\nطريقة الشرح : نوته ينزلها في البلاك بورد ، وانت تطبعها ويحل كل الاسئلة اللي فيها على السبورة… ( غالبا تكون اولدات )\nالكويزات : ٨ كويزات تقريبا ناسي كم بالضبط\nمستواها - صعبة أو متوسطة مائلة للصعوبة ، وممكن تعتبرها شي نسبي\nالمياجر:\nالفاينلات :\nالقريد النهائي: b+\nالصوت: انجليزي دائما بس واضح\nإضافات :\n- عنده واجبات كثيرة… وفي نفس الوقت عنده بونص كثير…\n- الدكتور مهتم ويتعب على الطلاب كثير ( البلاك بورد كل اسبوع ينزل اسئلة براكتس - اولد اكزامز - نوتات الشابتر اللي بتاخذونه الاسبوع القادم )\n- يحاول يضغط على الطلاب لمصلحتهم ، اذا انت من النوع اللي ما يحب ضغط المدرس فـ ممكن ما يعجبك\n- الكلاس وورك بيعطيك اكثر من اللي تتوقعه ، وبيضبطكم ان شاء الله\n- لو تمشي معه تمام اضمن لك قريد اكثر من اللي تتوقعه\nسلبية :\n- التصحيح في الكويزات شديد شويتين ، وتحتاج تكون دقيق في اجاباتك\n\nملاحظة : ممكن يغير طريقته لانه توه جديد ( ثاني سمستر له )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-al-mugrabi-math-002/176943/2", "user": "oria27", "ts": 1497885806000, "tid": 176943, "pn": 2}}', 1497885806000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p156828-math002', 'stk-user2057', 'MATH 002', 'info', '{"desc": "والله نصيحتي…\nلا تذاكر الكتاب خير شر!!\nاذا كان نوت مدرسك قوي ذاكره او نوت المسلماني او ايمن…\nوحل كم ميجر بس علشان ما تنصدم بالاختبار…باسئله غريبه…\nقبل ماتدخل القاعه كلم الوالد والوالده وخلهم يدعون لك…\nوالله يوفق الجميع لما يحب ويرضى\nوعندي حركه تعطيك معنويات اكثر قبل الاختباااار ((( سلم على المدرسين اللي بطابورك وادع لهم بالتوفيق)))\nههههههههههه <<< امززززح", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002-major-i/55345/8", "user": "user2057", "ts": 1173998270000, "tid": 55345, "pn": 8}}', 1173998270000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p156845-math002', 'stk-user1913', 'MATH 002', 'info', '{"desc": "انا اشوف ان الاسئلة في الكتاب ماتنفع في الاختبار انصحك بمذاكرة نوتس ايمن ممتازة جدا\nانا كان عندي السمستر الاول مدرس باكستاني من جنبها لكن مذكرة ايمن فادتني بشكل كبير\nوكثير من اللي عادو 001 اعرفهم معي يقولون يليتنا ندري عنها من زمان قبل الفاينال…وبالتوفيق ان شاء الله.\nبس ياريت تقولون لنا مين هذا ايمن لان كم من مدرس قال لي انه مايعرفه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002-major-i/55345/9", "user": "user1913", "ts": 1173999996000, "tid": 55345, "pn": 9}}', 1173999996000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1178599-math002', 'stk-ambitious_91', 'MATH 002', 'info', '{"desc": "سلام عليكم, الترم الأول ما كنت اذاكر كويس أول بأول وبعض الدروس ما انتبه للشرح, فاحتجت النوتة للرجوع لبعض الشروح, في النهاية عدت الماث 002 للاهمال وعدم الانتباه والمذاكرة\n\nالترم الثاني, نظمت أموري وفتحت الكتاب واحضر الكلاس وأنتبه للدروس كويس وما احتجت النوتة أبدا والحمد لله نجحت وانا فاهم, أهم شي اذا شي مو فاهمه روح للمدرس أو استخدم النوتة, لكن الكتاب أولا, هذه تحت نصيحتي وخطتي كيف تذاكر الماث, ان شاء الله تفيدك\n\nبالنسبة كيف تذاكر الماث MATH:--\n\n#1لابد الاطلاع على النظريات أولا, والنظر فيها بتعمق, وحفظها, وفهمها أفضل وأفود من حفظها! وأنظر فوقها وتحتها وقبلها وبعدها في الكتاب حتى تفهم وتزداد! فالشرح حولها وبينها, والنظرية الثابتة في مربع ملون!؟\n\n#2أنظر للأمثلة المحلولة بعد*النظريات أنظر سؤال وحل الآخر وأكتفي بالنظر في الرابع.\n\n#3أنتقل مباشرة بعد الخطوتين السابقتين لحل بعض أسئلة الكتاب وأختار الأعداد الفردية, وحاول أن تحل أسئلة متفرقة من أفكار متفرقة. مثلا, لا تطيل الحل في أمثلة و أسئلة متكررة المفهوم والفكرة وطريقة وضع السؤال ونفس السؤال!؟ انتقل لحل فكرة ونموذج آخر من الأسئلة في المفهوم!\n\n#4بعدالتأكد من فهم النظرية, والاطلاع على أمثلة الكتاب, وحل عدد لابأس به من أسئلة الباب. تنتقل للذي هو أهم\nالريساتيشن تقرأ السؤال وتفهم المطلوب ولا ترى الاجابات, ومن فهمك للنظرية وربطك للماث والتفكير ستبدع في الريسايتيشن, وركز على الريساتيشن لأنها تضمن فهمك الجيد وتقيم فهمك الحقيقي للسيكشن, أشر على بعض الأسئلة التي لا تعرفها واذهب Office Hours أو أنظر الحلول اذا لديك عندك العجز والتوقف لدى سؤال أكثر من 7 دقائق.\n\n#5آخر شي بعد أكمال تشابتر كامل في الماث مثل R و 1 و 2 واقتراب موعد الميجر. فقد كنت فاهم ودارس المواد للأختبار والسكاشن والتشبترات كويس. ولا يشترط 100% ؟؟؟ فقبل الميجر باسبوعين تحسب حسابك. وقبل الميجر باسبوع تكون في حل الأولد أقزام. أستغرق فيها 5 أيام أو 6 أيام من الحل, وتأشير الغير مفهوم والتماس المساعدة عند الآخرين!\n\nأهم ما أريدك تركز عليه في مذاكرة الماث!!! أفهم النظرية تمام وأحفظها في عقلك, أنظر الأمثلة فقط, حل عدد من أسئلة الكتاب ولا تكثر منها لأنها بدائية الفهم,\nفند وأدرس واستغرق وقت في الريسيتيشن, والنهاية أدرس وفند وافهم وأعرف أولد أقزام, اذا فعلتها أضمن لك النجاح وبسهولة وطمأنينة\n\nاذا أردت أي شي أخوي شرح, مسئلة, أنا حاضر في خدمتك, جمع كم سؤال وارسلي خاص ونتقابل,\n\nوالله يوفقك وييسر أمورك, خطط, التزم, أعمل, هذا هو طريق النجاح…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002/140027/9", "user": "ambitious_91", "ts": 1360321564000, "tid": 140027, "pn": 9}}', 1360321564000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p439446-math002', 'stk-abo_alhish', 'MATH 002', 'info', '{"desc": "3 اسئلة خطأبالاشارة:)\nوسؤال رسمت صح وعوضت صح وكل شي صح بس الانتيرفال خطا:)\\\nالحمد لله على كل حال \\\nوالله اسهل اختبار مر علي تقريبا\nولحد ينقز لي يتفلسف\nذاكرت له مذاكرة واحد بيجيب فل مارك\nواخر شي 14\nالحمد لله انا سويت اللي علي واللتوفيق من رب العالمين:)\n\"يمكن الاختبارات اللي فاتت اسهل بس انا كانت عندي صعبة لاني ما ذاكرت صح \"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/76053/36", "user": "ABO_ALHISH", "ts": 1249016209000, "tid": 76053, "pn": 36}}', 1249016209000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1196770-math002', 'stk-mesho160', 'MATH 002', 'info', '{"desc": "بالنسبة لي كان الاختبار متوسط الى صعب او بالعامية ( صعيب )\n\nقبل الاختبار ومع حل الأولد اكزامز تقريبا حليت اربعة واسئلة اضافية !\n\nلكن واجهت اسئلة ( دقرت ) فيها ولا عرفت احلها !\n\nتقريبا درجتي من 13 -14 ان شاء الله ما تنقص !\n\nقدر الله وما شاء فعل ، راح ارضى بالقدر ، لكن هذا لا يعني اني ما اشد في الميجر القادم واحاول اجيب فوق 18 !\n\nchange of base theorem ما ادري وين المشكلة ، فيني ولا فيها !\nيخلطون لك اربع او خمس خاص للوغاريتم الطبيعي والعشري ويقولون يله ، طلع الناتج !\n\nالحمد لله ، الاحظ ان مستواي في تطور عن الميجر السابق ، 001 كان وضعي غير مقبول نوعا ما ، اذا استمريت بنفس طريقي هذا ما راح اعدي في الجبل بقريد حلو !\n\nاتقفت مع مجموعة من الاصدقاء بتخصيص يوم ، الثلاثاء مثلا ، لحل و مراجعة دروس الاسبوع + حل الريسيتيشن ان امكن !\n\nبحيث لما يكون فيه كويز ، الا وانت فاهم 70 الى 80 % من الدروس !\n\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002/141664/18", "user": "Mesho160", "ts": 1362704889000, "tid": 141664, "pn": 18}}', 1362704889000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p548072-math002', 'stk-user5374', 'MATH 002', 'info', '{"desc": "اعدت ماث 002 ثلاث مرات( الصيف + و ترم 082 + 091)\nالسبب : قله المذاكرة + الاعتماد على نوت ايمن\n----\nذاكرت الكتاب فقط + حليت اسئله الواجبات بانتظام و كررت حل الواجبات قبل المياجر + اسئلة من الكتاب غير الواجب\n\nالنتيجة :B+\nكان يمديني اطلع للـ a , لكن السبب الكلاس وورك نازل بسبب الغياب + اهملت الكويزات + مافتحت المياجر القديمة ابداً .\nنصيحة : الكتاب شكله معقد ، لكن اذا استمريت عليه ما راح تستانس في المذاكرة الا منه …\nخذ نصيحة المجرب …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/84186/6", "user": "user5374", "ts": 1266778838000, "tid": 84186, "pn": 6}}', 1266778838000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p548166-math002', 'stk-equal', 'MATH 002', 'info', '{"desc": "- الكتاب اولا واخيرا للكونسبت الاساسي …\n- نوت العبسي … نوت ممتاز … تحصله في الجمعية …\n- حل افكار نوت خان … الرجل هذا ما هو بصاحي … عبقري رياضيات … وحكمت عليه من نوته !\n- هومورك ( ورقي او اونلاين واذا الاثنين يكون افضل ) وريستيشن بشكل اسبوعي …\n- اعرف اخطاءك في الكويزات والكلاس تست واستفيد منها …\n- اولد اكزام قبل المياجر والفاينل … وحل ( بيدك وليس قراءة فقط ) قد ما تقدر … يعني حاول تخلي يوم كامل لها قبل كل ميجر …\n- كويزات وكلاس تيست الزعبي … اعتبرها بمثابة اعداد للميجر لانها كويزات محترمة بمعنى الكلمة !\n- الحضور … وحاول ما تغيب عن اي كلاس واحضر بدري …\n- اوفس هور اذا عندك اي مشكلة … خصوصا اذا كان مدرسك من النوع اللي يقدر قدوم الطالب عنده …\n- حاول انك تفهم المادة اول باول ولا تراكم المواضيع … بالنسبة لي … احاول اذاكر بشكل اسبوعي …\n- ذاكر للكويزات كانك تذاكر للمياجر … وامورك طيبة ان شاء الله …\n\nطبعا الهدف من كل هذه النقاط هو الالمام بالافكار وطرق الحل الصحيحة … اما سالفة الاعتماد على نوت واحد … او نوت ايمن … فهذي ما تمشي ! بالتوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/84186/10", "user": "equal", "ts": 1266783659000, "tid": 84186, "pn": 10}}', 1266783659000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1257072-math002', 'stk-ahmad_baj', 'MATH 002', 'info', '{"desc": "أخوي صدقني إن ديمير من أفضل المدرسيين الي بيمرو عليك في الجامعة كلها …\n\nدرسني الترم الأول والترم الثاني … وما فكرت ولا لـ لحظة أغيره إلا لـ معاذ أبوجيا وما تيسر .\n\nالدكتور طيب جدًا وحبوب وفااااهم …\n\nصراحة شرحه يكون صعب لـ يبغى شرح من الصفر من الأساس مررة ما يناسبهم … لكن لو انت تفهم بسرعة فـ ديمير حيوفر عليك جهد كثيير في الدراسة .\n\nكنت أعتمد على شرحهه + حل اولد إقزام = a+ الحمدالله\n\nأهم شيء عنده احرص ان توضح لك انك مهتم ولو بالكذب . بيرفعك في الكلاس وورك كثير\n\nكان معانا واحد جاب الميجر الاول 14 والثاني 18 أو 19 اعطاء 24 في الكلاس وورك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148477/3", "user": "Ahmad_baj", "ts": 1377856152000, "tid": 148477, "pn": 3}}', 1377856152000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1257137-math002', 'stk-abo_yazeed6', 'MATH 002', 'info', '{"desc": "هههههههه يا اخي مدري ليش الناس تسبه ,والله كان كويس أخذت عنده 001\n\nأفرجنا كان 18 باعتمادنا على شرحه والاولد اقزامز “بس يبغالي اعترف انه الطلاب كانوا دوافير نوعا ما”\n\nشد حيلك معاه ,ديمير يحل المسائل الي عادة تجي في المياجر وما يضيع وقته في المسائل السخيفة ,ويمكن يعطيك اياها كبداية عشان تفهم الكونسبت\n\nكويزاته ذاكر من الاولد اقزامز ,تجي أحيانا نسخ لصق وفالك a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148477/6", "user": "abo_yazeed6", "ts": 1377865002000, "tid": 148477, "pn": 6}}', 1377865002000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p168500-math002', 'stk-red-devil', 'MATH 002', 'info', '{"desc": "تصدقوا شباب…\n\nأنا أقولها وكلي ثقة…\n\nأسئلة الماث 002 كانت سهلة…\n\nلكن أنا ما حليت تمام…\n\nوتصدقوا لمن الواحد يجي يفكر فيها…\n\nيعني قاعدين نذاكر لنا تقريبا كم يوم…\n\nوحلينا مياجر وأطلعنا على نوتات…\n\nبس كلو طلع بلش…\n\nوما أستفدنا شي…\n\nهوا الختبار سهل…\n\nلكن وقت الاختبار نحس اننا تنكات…\n\nصحيح انو المياجر حقت السنين اللي راحت كانت جدا تافهة مقارنة باللي عندنا…\n\nلكن برضو الاختبار كان سهل…\n\nعموما…\n\nالله ييسرها وما يحتاج نقعد صيفي…\n\nأنا دحين مني طايق نفسي…\n\nكيف في الصيف…\n\n@62@\n\nتحياتو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/56280/15", "user": "red-devil", "ts": 1179090281000, "tid": 56280, "pn": 15}}', 1179090281000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842125-math002', 'stk-_z_o_y_d', 'MATH 002', 'info', '{"desc": "-أنزل درجة ماث من خشيت الجامعة كانت لـ الميجر الثاني 002 …\n-أعرف واحد أفرج درجاته بالماث تقريبا 90% … لكن بالميجر الثاني002 جاب 14 من 22 …\n\nدفعه مغضوب عليها\n\nواعرف ان كل دفعة بتقول هالكلاام …\nانتوا قلتوها…واحنا قلناها قبلكم…واللي قبلنا قالوها بعد …\n\nو ع فكرة… الميجر هذا هو ثاني أصعب اختبار مر علي من بين 14 اختبار…\n\nاذا بتفكر بدرجتك اللي اخذتها من ذا الاختبار…فـ فكر كيف تعوضها…! فقط لاا عير…\n\nموفقين…🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-2/107348/14", "user": "_Z_O_Y_D", "ts": 1304871597000, "tid": 107348, "pn": 14}}', 1304871597000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842130-math002', 'stk-vip_master', 'MATH 002', 'info', '{"desc": "صارلي ثلاث سنين في الجامعه وللحين ما انسى ميجر الماث الثاني ل 002\nللحين اشوف اسئلته وانا نايم ( مع اني جبت في مواد كثير في الجبل درجات اقل ) لكن هذاك الميجر الله لا يوريكم\n\nاذكر سؤال للحين اسهل سؤال جابوه جوابه كان يعتمد على معادله صغيره لكن ما قدرت احله لانه بطريقتهم خلو حله يعتمد على رسمه متعلقه بالساين او السيكن من الشابتر الاولى الي ماهي في الميجر\n\nوافرجنا اذكره مو بعيد عنكم ودرجتنا مثلكم لكن عدينا وبالسي بلس بعد , ( درجتي ميجر ون عل الافرج والثاني تحت الافرج )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-2/107348/15", "user": "VIP_Master", "ts": 1304872753000, "tid": 107348, "pn": 15}}', 1304872753000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842131-math002', 'stk-_1148', 'MATH 002', 'info', '{"desc": "يا شباب خذوها نصيحة من طالب كان مكانكم العام الماضي ل 002 ومجموعي بالمياجر كان نازل\n\nلا تنسون ان الفاينل عليه 36 هذا العام الماضي مدري الحين كم عليه\n\nلكن النقطة اللي بوصلها ان الفاينل عليه درجات كثييييرة وصراحة كان سهل وبمتناول اليد يعني اذكر كان فيه 25 سؤال هدية وبمتناول اليد للطلاب\n\nعلشان كذا انسوا اذا جبتوا درجة سيئة وركزوا على الفاااااااينل لسهولته مقارنة ب ميجر 2 ولكثر الدرجات فيه\n\nوموفقين يا رب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-2/107348/16", "user": "_1148", "ts": 1304872795000, "tid": 107348, "pn": 16}}', 1304872795000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1047497-math002', 'stk-alhakem', 'MATH 002', 'info', '{"desc": "اتوقع الدكتور حقك هو اللي ينزلها\nيعني تجيه درجاتكم كاملة وهو يسوي submit\nوالله أعلم\nملاحظة: الفيزياء نفس الشي المدرس هو اللي ينزلهم بالبورتال بعد ماتجيه كامل الدرجات <<هالكلام مؤكد 100 %\n\nالفائدة ان الدكتور يعطي زيادة درجات لو احتاج\nمثلا انا أعرف واحد في الماث 002 هذا السمستر 112 مياجره 14 -17 على التوالي …دكتوره عطاه 22 كلاس وورك\nجاب في الفاينل 35 !!\nدكتوره عدّل له الكلاس وورك وخلاه 24 … وحصل على قريد A\n((اتوقع الدكاترة مايعدلون الا اذا شافوا هناك فائدة…يعني مثلا لو زاده في الكلاس وورك بيرفع قريده)\nيمكن أيضا اللي بيرسبون يعدلون درجاتهم لو احتاجوا بعد بس ما عندي علم إذا حد حصل له هالشي !\nطبعا الدكتور اما يكون كريم والطالب يستاهل(مثلا مايغيب) …\nأو الدكتور كريم والطالب مايستاهل …\nوالعكس صحيح\n\nأنا أقول شوف أحد تعرفه من كلاسكم الماث اذا هم بعد مانزل لهم في البورتال…لأن اذا مانزل يعين ماعندك مشكلة فقط أصبر\nاذا نزل لهم ارسل ايميل لدكتورك عشان يشوف حل\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-grade/126597/4", "user": "alhakem", "ts": 1338295803000, "tid": 126597, "pn": 4}}', 1338295803000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1444411-math002', 'stk-mr.a1', 'MATH 002', 'info', '{"desc": "أول مرة أدري إن الماث Co-requisite مع الاسلامي [emoji23]\n\nالخطة المذكورة فوق جميلة جدا وتقدر تسجلها بدون أي مشاكل\n\nبالنسبة لسؤالك عن MATH 101: الكورس سهل لكنك راح تحتاج MATH 002 فيه ، فإذا كنت فاهم 002 وحافظ المتطابقات الموجودة فيه راح يسهل عليك كثير\nالمعضلة الوحيدة فيه هي انك تحتاج تحل عدد جيد من الاولد اقزام حتى تجيب +A ، واللي هي مو مستحيلة في هذا الكورس ولا صعبة\n\nأنا اخذته في ترم 151 - ترم الجلد [emoji16] - ، وما قمت اذاكر باجتهاد الا مع ميجر 2 وجبت +B بمجموع 307\nيعني لو تشد صح فيه بتقدر تطلع بقريد بكل سهولة\n\nأما الانجلش فهي مادة ما تحتاج مذاكرة ابد\nكلها عبارة عن 4 تاسكات ، 2 ريدينق كويز ، وميدترم بيكون بين مياجر الماث\n\nأهم شيء شوف الدكتور اللي بينزلها ، اذا مو كويس احذفها ونزل مادة ثانية ، اذا تقدر على ICS 103 نزلها\n\nيعني الخطة سليمة ومو متعبة مرة ، بس يبغى لها شدة حيل\n\nموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172661/6", "user": "Mr.A1", "ts": 1458373907000, "tid": 172661, "pn": 6}}', 1458373907000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1212313-math002', 'stk-undefined', 'MATH 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاتة …\n\nانتهينا قبل قليل من الميجر كل واحد يعطينا انطباعاته عن الميجر … ووكم درجة صعوبة الاختبار من وجهة نظرة\n\nب النسبة اللي اجتهدت لاكثر من اسبوع متواصل مذاكرة جادة ونوم 3 ساعات فقط دخلت الاختبار قلت الله يكتب اللي فيه الخير ولكن !!\n\nوجدت صعوبة قليلة في الاختبار مع ان اغلب الاسئلة محتاجه شوية تركيز فقط لكن الحمد لله على كل حال …\n\nانتظركم 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-math002/143356/1", "user": "Undefined", "ts": 1366283809000, "tid": 143356, "pn": 1}}', 1366283809000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p346109-math002', 'stk-d_a_r_k_h', 'MATH 002', 'info', '{"desc": "الأفرج الحقيقي هو 50.5 ( على كلام الدكتور الرصاصي )، يعني ارتفع ثلاثة درجات تقريبا ً عن الأفرج المعروض في الموقع، والسبب هو الخلل في كونهم حسبوا درجات الطلاب اللي أخذوا صفر ( بمعنى أصح: اللي دردبوا الكورس )…\n\nبالتوفيق… والاختبار كان اختبار ماث 002 بدرجة أولى ومن ثم كالكلس… أعتقد إن قوتهم في الجبر أكبر من قوتهم في الحساب…\n\nتحيتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/69001/20", "user": "D_a_r_K_h", "ts": 1230758835000, "tid": 69001, "pn": 20}}', 1230758835000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509429-math002', 'stk-amo', 'MATH 002', 'info', '{"desc": "math 002 term 182\nالتحضير : ما يحضر بالدقيقة ومتساهل بالليت بس لا تفلها ويسمح بالميك اب بس ارسل ايميل احتياط\nطريقة الشرح : من النوتة حقته ولا انصح بها\nالكويزات : على المود شي صعب وشي سهل\nالمياجر: كومن\nالفاينلات : كومن\nالبونص: فيه بونص عام غالبا يكون درجتين وفيه بونص خاص للي بيرسب والي بيجيب اي بلص\nالقريد النهائي: +B\nالصوت: جيد واللهجة واضحة\nإضافات : الدكتور حبيب وجيد لكن يحتاج أن يرتقي بشرحه لمستوى الكويزات اذا خلاها صعبة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-qureshi/180034/2", "user": "AMO", "ts": 1557229332000, "tid": 180034, "pn": 2}}', 1557229332000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p377574-math002', 'stk-maystroooo', 'MATH 002', 'info', '{"desc": "بالنسبة لي !!\n\nإلى الحين ما عجبني شي كثر نوتات الشرقاوي …\n\nصحيح نوت محمد خان كويسة … بس شفتها كذا مرة مع روميتي تكون مو مرتبة …\n\nأما الشرقاوي صراحة تاعب عليها …\n\nفي السمستر الأول ما كنت أعتمد إلا على نوتات شرقاوي + الأولد إكسام … بالعربي الكتاب ساحب عليه مرررررة …\n\nوالحمدلله طلعت بدرجة b مع أني ما كنت أذاكر إلا وقت الاختبارات …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002/71211/11", "user": "MaYsTrOoOo", "ts": 1236443788000, "tid": 71211, "pn": 11}}', 1236443788000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p854962-math002', 'stk-guest', 'MATH 002', 'info', '{"desc": ".\n.\n\nمن أصعب المواقف اللي مرت علي بالتحضيرية\n\nفي ميجر 2 ماث 002\n\nآنتهى الوقت و كان الدكتور العطاس يقول Stop Writing\n\nو أنا مدهرررر حل 😆\n\nلين جآء و سسسحب الورقة مني 😲\n\nو شطب عليها 😞\n\nتصحح الآختبار و رجعه الدكتور\n\nو ما رجعت لي ورقتي 😲\n\nقلت أنا خلآص شكلها زيروووو 😐\n\nو صيفنآ في الجآمعة آحلى 😞\n\nخصوصآ إني مخبص في ميجر ون 😞\n\nرآجعت الدكتور العطاس\n\nفي بريك الغدآ\n\nو أنوووآإع اللعب بـ الآعصاب 😁\n\nلقيته مصححهآ …\n\nو جايب درجة زينتن بالحيل مرة 😆 😏 🚬\n\nيومها سحب على الدوام\n\nو فال أوم أوم أوم اليوم\n\nشعور لآ يوصف\n\n🤴\n\n.\n.\n\nبس يآهي خررررررشة 🤠\n\n.\n.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/108548/4", "user": "Guest", "ts": 1308416309000, "tid": 108548, "pn": 4}}', 1308416309000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p560002-math002', 'stk-dead_boss', 'MATH 002', 'info', '{"desc": "السلام عليكم شباب اولا كيف هي الطريقة الصحيحة لمذاكرة الماث002 لاني اذاكر يوميا بس ما اجيب نتيجة بذات في الكوزات انا طريقة مذاكرتي هي النوت الدكتور واسئلة الواجب بس احس مذاكرة كذة غير كافي او غير صحيحة ابي طريقة من الف الى الياء لاني ناوي ان شاء الله على a بلس ومعليش على اطالة 🤓 🤓 🤓 🤓 🤓 🤓 🤓😉", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85015/1", "user": "DEAD_BOSS", "ts": 1267903410000, "tid": 85015, "pn": 1}}', 1267903410000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p560029-math002', 'stk-saudi_kfupm', 'MATH 002', 'info', '{"desc": "وعليكم السلام\nشوف اخوي انا من وجهة نظري الكتاب أفضل من شرح اي مدرس في العالم مليون مره\nلكن بحكم ان chapter 4 نصه محذوف وفيه لخبطة فأنصحك تذاكر نوت خان والهووموركات\nوبالنسبة للمياجر لا تخاف مع الاولد اكزام كل شي بيصير سهل\nاهم شي انك تكون فاهم المنهج بعد كذا اقرا الاولد اكزام وامتص اكبر قدر ممكن من الافكار وابشر بـ A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85015/2", "user": "saudi_kfupm", "ts": 1267904673000, "tid": 85015, "pn": 2}}', 1267904673000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p560254-math002', 'stk-user6690', 'MATH 002', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nمادام انك ناوي عــ a+ الله يبلغك مرادك وتراها باذن الواحد الاحد سهلة بس يحتاجلها شوية شغل\n\nشوف نصيحتي لك\n\nالدرس اللي تاخذه رح افتح الكتاب وحاول تحل عليه اكبر عدد من المسائل مو شرط فردي على قد ماتقدر حل\n\nبعدين في يوم الخميس امسك اسئلة ابوجا او اشرف الجمال اللي كل تشابتر لو حده وحلها كلها واذا لقيت\n\nشيء ما انت فاهمه لا تأجل رح للمدرس في الاوفس اور واسأله\n\nواهم شيء لاتشد في الماث وترخي بالانقلش\n\nوالله يكتبلك التوفيق يا الغالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85015/5", "user": "user6690", "ts": 1267918603000, "tid": 85015, "pn": 5}}', 1267918603000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p560480-math002', 'stk-user4636', 'MATH 002', 'info', '{"desc": "نصيحة مجرب\n\nالكتاب اسهل شي وافضل شي واسرع شي للمذاكره\n\nحل الامثله اللي بالكتاب واذا خلصت ذاكر الاسئله الOdd اللي بآخر الكتاب وشوف حلها بنهاية الكتاب\n\nوحاول تكون مخلص المنهج قبل الميجر باسبوع عشان تراجع من نوت المدرس الرائع خان او ابوجيا كلهم نوتاتهم روعه\n\nوايضا لازم تحل الاولد اكزامس\n\nوبالتوفيق يالغالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85015/6", "user": "user4636", "ts": 1267963139000, "tid": 85015, "pn": 6}}', 1267963139000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p377537-math002', 'stk-user4917', 'MATH 002', 'info', '{"desc": "شباب ان طالب ادرس ماث 002 وماني فاهم شي:( وهذا احنا في اول شابتر\n\nالي يقولون انه اسهل شابتر 😍 .فما ادري ايش راح اسوي في الشباتر الجايه\n\nشباب والله اني خايف اصيف في الجامعه… فالله لايهينكم الي عدا 002 يعطينا\n\nنصايحه وكيف الدروس هل هي اصعب من البدايه بمراحل ام لا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/71297/1", "user": "user4917", "ts": 1236441278000, "tid": 71297, "pn": 1}}', 1236441278000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p377620-math002', 'stk-gowa_3youni', 'MATH 002', 'info', '{"desc": "كان يدرسني الزعبي ،، وعشت معاه أسوأ لحظات حياتي\nوما كنت أدري وش اللي يخليني أواظب على حضور كلاساته\n\nوهالحين ومع أن أني سمعت أن الماث 002 أصعب بكثير من 001 وخاااااااااصة تشابتر 6 - ركزوا عليه-\nإلا اني أحس انه حيكون أسهل مع مدرس مثل الشرقاوي اللي يدرسني هالسمستر\n\nلكن مهما يكون المدرس ممتاز لازم الواحد يشد حيله لأن المدرس ما بيجي يختبر بدالك وشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/71297/4", "user": "gowa_3youni", "ts": 1236447532000, "tid": 71297, "pn": 4}}', 1236447532000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p379019-math002', 'stk-user4368', 'MATH 002', 'info', '{"desc": "السلام عليكم\nأخي الكريم رنين الصمت\nكيف حالك\nلعلي أنقل لك تجربتي\nفي ذلك السمستر مررت بظروف صعبة جداً ، أثرت علي في الدراسة ، و المنهج كذلك كان صعب ، كان عندي الأصل أني باخذ f بلا شك\n\nو لكن و لله الحمد تداركت نفسي بالآتي\n\nذاكر يومياً\nاذا نوت الدكتور جيد اكتب معه لانه راح يفيدك أكثر من غيره\nحل أكبر قدر من الأمثلة\nحل الهوموركات\nإذا ما فهمت شيء روح للدكتور على طول في مكتبه\n\nو الحمد لله عديت الكورس و جبت +\n\nو بالتوفيق ان شا الله\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/71297/10", "user": "user4368", "ts": 1236681814000, "tid": 71297, "pn": 10}}', 1236681814000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p379215-math002', 'stk-user4109', 'MATH 002', 'info', '{"desc": "وجلال الله ياناس ياهو سهل الـ002\nاسمعوا قصتي\nانا كنت مهمل فيه ماكنت اسلم هوم ووركات واغيب عن الكلاسات\nوالمذاكرة زفت وجبت فيه دي بلس رسبت بفارق درجتين بس\nمع العلم اني كنت اشوفه اصعب كورس في حياتي ياهي اشياء\nعجيبة مرت علي ياهي تخاريف ياهو شابتر 5 على 6 والله اقعد في\nالكلاس فاك فمي والمدرس يشرح\n\nاخذته في الصيف جبت فيه ايه\nو والله هذا انا اقوله انه من اسهل الكورسات خخخخخ\nواسهل من الـ001\nمفتاح النجاح من وجهة نظري الهوم وركات الهوم وركات الهوم وركات\nوالله ياشباب انها 90 بالمية من النجاح +قليل من الانتباه مع المدرس+\nالمذاكرة كل يوم والمذاكرة كل يوم ياشباب تراها مهمة\nوفالك الايه بلس\nملاحظة\\ماكنت اخذ نوت مع المدرس كنت اعتمد على الكتاب 100%\nلايفوتكم تراه شيق ولغته سهلة موب زي مناهج الثانوية\nبالتوفيق لكم يافطافيط", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/71297/13", "user": "user4109", "ts": 1236706148000, "tid": 71297, "pn": 13}}', 1236706148000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1206692-math002', 'stk-smile-more', 'MATH 002', 'info', '{"desc": "أبدأ من الحـين سوي جدول يشمل جميـع الأقسام إلي معنا، و حاول تنهي المنهج قبل 3 أيام أو يومين من يوم الإختبار ; علشان تمخمــخ عـلى الأولد إقزام + الريسايتيشن\n\nأنصحك بهالطريقـه :\n\n1- تقرا شرح الكتاب جيدا + حل إلي تقدر عليه من الأسئله الفرديه ( و شوف الحلول اخر الكتاب )\n2- أشتري نوته إبراهيم ناجي ( مفيده جدا جدا جدا ) و ذاكر منها. ( المذكره فيها أسئله +A )\n3- لمن تخلص مذاكره تشابتر 6 من الكتاب مثلا، أبدأ أقرا و حل أسئله نوته إبراهيم ناجي. ( و كمل على نفس النمط ).\n4- أدخل موقع الـ Pyp و حل الأولد إقزام + الريسايتيشن.\n\nو كذا أضمنلك الـ A+ ، A إن شاء الله .\n\nلا تنسانا من الدعاء.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/142773/3", "user": "SMILE-MORE", "ts": 1365271394000, "tid": 142773, "pn": 3}}', 1365271394000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1207199-math002', 'stk-iicreative', 'MATH 002', 'info', '{"desc": "انا السنة الي راحت كنت اوريا … لو يرجع الزمن ما راح اذاكر الرستيشن ابدا …\nاهم شي افهم المنهج سواء ذاكرت من الكتاب او من نوته اهم شي تكون فاهمها+بحل الاسئلة الفردية الي في نهاية كل سكشن+بحل 2 اولد اكزام قبل الاختبار واكون فاهمها مضبوط…\n\nالله يوفقك يالغالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/142773/8", "user": "iiCrEaTiVe", "ts": 1365368609000, "tid": 142773, "pn": 8}}', 1365368609000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1067515-math002', 'stk-alqalem', 'MATH 002', 'info', '{"desc": "أخوي السؤال واضح وسهل\nأول شيء أخذ عامل مشترك\n2 cos ثلاثة ثيتا\nوقسم عليه\n\nوبعدين أخذ عامل مشترك جذر ثلاثة وقسم عليه\n\nوطلع له الخطوة الثانية\n\nوبعدين طلع أن كوساين = جذر ثلاثة على اثنين\n\nيعني “باي على ثلاثة \" أو بالدرجات \" 60”\n\nوحط الإجابة + 2kباي ، عشان تشمل جميع الإجابات\nوبعدين سوى نفس الشيء لكن بالنسبة للسالب\n\nالخطوة الأخيرة في الشق الأول من الإجابة ، كان عبارة عن القسمة على عامل ثيتا ، يعني قسم على ثلاثة\nحتى تبقى ثيتا\n\nبعدين بدأ في الشق الثاني من السؤال واللي هو cos3 = 1\n\nوطبق نفس الخطوات\n\nراجع أسئلة النوتات الموجودة في موقع الهومورك اونلاين موجود هذا السؤال بالتفصيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/128781/2", "user": "Alqalem", "ts": 1342318634000, "tid": 128781, "pn": 2}}', 1342318634000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p844553-math002', 'stk-_saad', 'MATH 002', 'info', '{"desc": "السلام عليكم جميعا, شوف أخوي الكريم أنا أحييك على همتك وروح نزل صيفي والله معاك لكن في كم نقطة أحب أذكرها لك للفائدة بحكم إني مجرب أحذ ماث 002 في الصيف (لأول مرة) :-\n1- الصيف سريع جدا يعني إحسب حساب أول ما تبدا بعد أسبوعين ونص إلين ثلاث أسابيع راح يكون عندك ميجر.\n2- الشرح راح يكون سريع بعد يعني المتابعة والمذاكرة أول بأول هذي لاااااازم وإلا راح يجيك ضغط مو طبيعي.\n3- الدراسة في رمضان مشكلة كبيرة (بالنسبة لي أنا لا أعلم عن غيري) لأنك راح تداوم الصباح وأنت صايم وغير كذا ما راح تقدر تذاكر وأنت صايم فا وقت المذاكرة المتاح لك قليل جدا وإحتمالية الغياب ترتقع (أنا عن نفسي بغيت أخذ dn في أخر أسبوع من الدراسة لأني غبت 9 غيابات و dn من 7 وكانوا 8 منها في رمضان ورمضان عندنا كله أسبوعين (يعني 10 أيام ما حضرت منها إلا يومين).\n\nعموما روح والله يوفقك وشوف أنا أحذت ماث 101 والإسلامي 201 والمادتين مره سهله خصوصا الماث سهل جدا حاول إنك تجيب ال a+ لأنها في متناول اليد.\n\nبالتوفيق للجميع…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107569/6", "user": "_Saad", "ts": 1306678992000, "tid": 107569, "pn": 6}}', 1306678992000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605476-math002', 'stk-dark_prince', 'MATH 002', 'info', '{"desc": "انا لله وانا اليه راجعون\n\nيا رب استر علينا\n\nاحنا وش سوينا فيهم علشان يعذبونا كذا\n\nاختبار اول صعب واختبار ثاني مستحيل\n\nوالله اني ذاكرت وتعبت ما خليت سؤال في الكتاب ما حليته لكن وش نسوي الله كريم\n\nرغم اني متأكد ان نتيجتي كارثية لكن ما بتفرق معي لأني سويت اللي علي والباقي على الله\n\nيارب يا كريم عدي هالترم على خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/26", "user": "Dark_Prince", "ts": 1273763352000, "tid": 88032, "pn": 26}}', 1273763352000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605514-math002', 'stk-user6966', 'MATH 002', 'info', '{"desc": "احلى رد شفته في هالموضوع هو رد رقم 32 وخصوصاً هالجملة :\n\nيعني لو ما نذاكر بعد لاحول ولا قوة بالله بس والله نفحط تفحيط\n\nمع أنه الماث حصة وياخذ وقت اكثرمن الأنجليزي اللي هو اربع ساعات\n\nبصرااحة كلام في الصميم !! هي اربع ساعات في الأسبوع , ويحتاج مذاكرة اقل !!\nيعني شكلهم هم رافعين عدد ساعات الانجلش بس عشان ما تذاكر ماث لووول وما تحس انه سهل .\n\nنعود للميجر , بصـراحة , وصلت لنص الأسئلة وانا يمكن ما حليت الا واحد , دجيت دججججة قووية !!\nجاني احباط , لكن كان هدفي لما وصلت نص الأسئلة اني اجمع اكبر قدر ممكن من الدرجات عشان ألعن أبو الفاينل !!\n\nباختصار “أنا أوريك يا الفاينل !!!!!!!!!!!!”", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/36", "user": "user6966", "ts": 1273766001000, "tid": 88032, "pn": 36}}', 1273766001000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605539-math002', 'stk-abdullah_al_shammari', 'MATH 002', 'info', '{"desc": "ترا بالنسبه للأ نجلش تحتاج ساعات كثيره عشان تتعلمها وتتقن النطق والكتابه as well < مو مثل الماث\n\nأما بالنسبه للماث فـ عندي لكم كم نصيحه أيام ما كنت مثلكم ( أوريا 🙂 )\n1- حل اود نمرز لكل سكشن وتأكد أن حلك صحيح , عشان تعوودك على سرعه حل الاسئله بوقت الاختبار\n2- وأذا خلصت من مذاكرة المنهج + حل الاود نمرز -> يبقالك خطوه أخيره وهي : أمسك 2 أو 3 اود أكزامات وحلها\n\nوأذا أتبعت ذي الطريقه راح تطلع بقريد عالي\n\nونظام أغلب الشعب : يجي بالبدايه يمسك اولد أقزام ويعرف كيف طريقة الحل ويرجع يحلها من أول ( كنه مسوي شي جديد ) وبالاخير يقول حليت اولد أكزام ولا طلعت بنتيجه < فـ هذي طريقه خاظئه\n\n🌹\nوفالكم A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/39", "user": "Abdullah_Al_Shammari", "ts": 1273768191000, "tid": 88032, "pn": 39}}', 1273768191000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605585-math002', 'stk-aliiii', 'MATH 002', 'info', '{"desc": "يا أخي الجامعة غير شكل … في العادة إختبار سهل وثاني وسط وثالث صعب\n\nأما الميجر الأول صعب والثاني أصعب !! والفاينل أكيييد بيكون دمااار …\n\nليه هذا كله !!\n\n(تلاقي اللي حط الأسئلة شاف الردود بعد الميجر الأول … وأنه كل واحد قال بنذاكر للميجر الثاني وبننجح غصبٍ عليه … فقال هذا وجهي لين جبتوا درجة أعلى ) 😆\n\nما أبغى أقول صيفنا حلو في الجامعة … لأنه بيكون مررر\nيعني إحنا اوريا … نداوم أكثر من الجبل … وتعب وقلق ومدري ايش …\nوبعدين يبون يجلسونا للسمر زيادة !! رحمتك يارب 😢\n\nاللي يذاكر واللي مايذاكر مابينجح … 😦\nاللي يقطع الكتب بينجح على الحفة 😏\nاللي يحضر ساعة الكلاس يوميا ويحل كل مسائل الكتاب\nويزعج المدرسين ويصرف 3 ساعات غير ساعة الكلاس بيتفوق بـ B إلى A\n\n60 درجة للنجاح كـ مينيموم … أبي أطلع فوق 59… بس مافيه فايدة … تنكسر رقبتي 😃\n---------------------\nسوري على الاطالة … فرغت همومي 😊", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/48", "user": "aliiii", "ts": 1273771417000, "tid": 88032, "pn": 48}}', 1273771417000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605633-math002', 'stk-_aiman', 'MATH 002', 'info', '{"desc": "بالرغم من انه اختبار الفيزيا من العن اختبارات الحياه يبقى اختبار الماث 002 الميجر الثاني اصعب اختبار عمره قابلني\n\nالفيزيا ما احل لاهمالي في الماده نتيجة لاهمال المدرسين نفسهم\n\nاما الماث فكنت ادرس له دراسة من جد\n\nالي يعدي ماث 002 فاهمه فهما صحيحا حتى لو باقل شي c\nراح تكون بقية كورسات الماث تافهه له", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/54", "user": "_aiman", "ts": 1273775272000, "tid": 88032, "pn": 54}}', 1273775272000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605951-math002', 'stk-mr-3b0d', 'MATH 002', 'info', '{"desc": "انا درسني الجندي السمستر الاول\n\nاو بالاصح كان مدرسي لكن ما درسني\n\nوالحمد لله عديت\n\nوالحين الشرقاوي الحمد لله مدرس جامد\n\nلكن صدقني بدون مجهودك الوضع نفسي الشيء\n\nانا يوم كان يدرسني الجندي كنت ابدا من اول وجديد واتعب كثييير صراحة:اشيل هم\n\nلكن الحين مرتاح ولا اذاكر اقول ايه فاهم ان شاء الله لكن الواقع العكس\n\nواكبر دليل الدرجات الحين في انخفاض .\n\nلكن يا شباب ترى انتوا خليتوا المدرسين اضعف مدرسين وخليتوا الاختبار اختبار لكورس ثاني\n\nشوفوا صح الاختبار كان صعب لكن مو لهالدرجة اللي تقول عليه كانك داخل كورس ثاني\n\nمع احترامي للجميع يا شباب\n\nالجامعة تبي واحد يفكر مب يحفظ ويجيك في الاختبار واذا قلبوا اماكن كلمتين قال اوف هذي ما قد جتنا\n\nعموما بالتوفيق وان شاء الله الافرج نازل^_^", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/91", "user": "mr-3b0d", "ts": 1273824149000, "tid": 88032, "pn": 91}}', 1273824149000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p608250-math002', 'stk-free_styler', 'MATH 002', 'info', '{"desc": "شباب كل المياجر بالنسبة لدفعتنا كانت سهلة معدا الاخير ولكن هذا ليس رأي … هذا رأي الاغلبية ( منهم ابوجيا )\nانا رأي انه المياجر كلها كانت سهلة حتى الان …\nو كنتوا تقولوا انه هالدفعة دفعة الدوافير و هذه الدفعة غير هي اللي راح تكسر راس الجامعة و اتاكم الرد المسكت تماما من الجامعة و هو الميجر اللي فات مع انهم بس صعبوا الهرجة حبيت بيدتوا تصارخوا وبالنسبة للقاله الاخ Euler على المايجر تراه صحيح 100% لأني انا اوافقه الرأي و هذا لأنني افضل متيريل ميجر 2 على 1 …\nمتى راح تفقد الجامعة سمعتها و مركزها !!؟؟\nلمن يعدي 75% من نفس الدفعة السنة التحضيرية بجدارة في سيمسترين و لكن هذه الدفعة ما بتكون دفعتنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-02/88195/31", "user": "free_styler", "ts": 1274025927000, "tid": 88195, "pn": 31}}', 1274025927000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605802-math002', 'stk-user6810', 'MATH 002', 'info', '{"desc": "والله يا شباب الاختبار ما كان مستحيل الحل بالعكس بس ركز شويه وحل وصدقني سهالات .بس 7 اسئله كانت صعبه شويه بس كان يمديك تحلها لو استبعت بعض الاختيارات المستحيله\n\nوبالنسبه للسؤال الي كان فيه خطا اعطونا 5 دقايق زياده = وقت سوال واحد 🤴\n\nيمكن الطلاب الافاضل يقولوا انه كان صعب لان هم حاطين في بالهم:( (002 exam 2) صعب\n\nوالمهم ان شاء الله الفاينل بيكون سهل وفكر في الفل مارك من دحين 👍\n\n🌹وبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/77", "user": "user6810", "ts": 1273788416000, "tid": 88032, "pn": 77}}', 1273788416000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p606166-math002', 'stk-alz3eem', 'MATH 002', 'info', '{"desc": "شباب ما تلاحظون انهم يبون يرسبون اكبر عدد من الطلاب هالسمستر\n\nيعني ستاندر ومياجر صعبه وافكار جديده\n\nالشي اللي يقهر اني بعد ما خلصت مذاكره حليت الاود اكزامز زي الحلاوة\n\nبس الميجر كان كله افكار جديده\n\nعالعمووم احس اني اذا نجحت باروح للقسم وباقولهم نجحت غصبن عليكم <<< مقهووور 😡\n\nاذر وايز يو آر ريسونسبل 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/96", "user": "alz3eem", "ts": 1273843090000, "tid": 88032, "pn": 96}}', 1273843090000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p606754-math002', 'stk-y-o-u', 'MATH 002', 'info', '{"desc": "ترى على فكره ، هي ماهي مسأله وقت مذاكر ، هي مسأله جوده المذاكره\n\nيعني لو تذاكر أسبوع بذمه راح تجيب فوق الـ 11 بالراحه او يمكن فوق 17 .\n\nطبعا بالنسبه لي اشوف الاختبار صعب ، لكن زهقت من كثر الي يقولون ذاكرت مليون يوم بس في النهايه طلع الاختبار صعب . يعني افهمها مذاكرتك أي كلام .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/103", "user": "Y-O-U", "ts": 1273872972000, "tid": 88032, "pn": 103}}', 1273872972000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p607030-math002', 'stk-f_3_r_a_s', 'MATH 002', 'info', '{"desc": "والله العظيم مافي شي ماسويتو\n\nبديت مذاكرة من قبل الميجر باسبوع ونص تقريبآ\n\nنوت خان - اولد اكزام - اود نمبرز - نوت يوشع - ريسايتيشنز\n\nوالله اني نسيت ايش معنى كلمـه \" فله \"\n\nوكل ماخرج من الدوام اروح المكتبه اذاكر\n\nوالله حرااااااام عليهم والله حراااام … طلــعو فينآ اولد آكزام جديد تستفيد منو الاآجيال الجآيه !!!!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-exam-ii/88032/110", "user": "F_3_R_A_S", "ts": 1273919555000, "tid": 88032, "pn": 110}}', 1273919555000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p750680-math002', 'stk-omar.s', 'MATH 002', 'info', '{"desc": "راح اقولك تجربتي في ماث 002 في ترم 092\n\nجبت في الميجر الاول 10 من 22 … والميجر الثاني 10 من 22 …\nوالكلاس وورك 8 من عشرين\nيعني مجموعي الكلي قبل الفاينل 28\n\nوكان فيه كلام كثيررررررررر ومن مدير القسم نفسه ! انه النجاح راح يكون من ستين\nيعني لازم اجيب بالفاينل 32 من 36 عشان انجح\n\nلكن انا شديت وحيلي وسويت اللي علي والحمدلله\n\nوجبت 29 بالفاينل … يعني اكثر من درجتي في الميجرين + الكلاس وررك\n\nوالحمدلله طلع الافرج 56 … وانا جبت 57\nوعديت الكورس الحمدلله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99535/8", "user": "OMAR.S", "ts": 1293159859000, "tid": 99535, "pn": 8}}', 1293159859000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443305-math002', 'stk-breaktheunbreakable', 'MATH 002', 'info', '{"desc": "أنا أخذت اختبار البروموشن في هذا الترم.\nالاختبار كان صعب جدا like hell وأصعب من اختبارات الميجر الأول والثاني وأمثلة البروموشن والنهائي لـ002.\nمع أن مستواي عال في الرياضيات وحصلت على A في 001 وكنت قريب من A+ ومذاكرتي لـ002 في الإجازة ومعرفة أغلب ما فيه، لم أقدر على حل أكثر من 7 أسئلة في اختبار البروموشن مع انتهاء الوقت.\n\nعموما الحمد لله الآن أغلب درجاتي في 002 عالية ولا أحتاج للمذاكرة كثيرا.\nبالنسبة لدرجة النجاح على ما أعتقد هي بين 70% و100%. اللي سمعته هو أن طالبين فقط نجحا من 20 طالب في الاختبار السابق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/02-promotion/172431/3", "user": "BreakTheUnbreakable", "ts": 1456592153000, "tid": 172431, "pn": 3}}', 1456592153000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438195-math002', 'stk-edencian', 'MATH 002', 'info', '{"desc": "نصيحتي لك … بالماث دائما وابدا … Practice all the time … وحاول تحل جميع اسئلة الكتاب ومن اول مايبدا الترم خذ لك اولد اقزام من الجمعية…\nخذ هذه الخطة المبسطة اللي تخليك باذن الله تاخذ مابين B الى A+\n1- بمجرد ماتاخذ الدرس ارجع للغرفة واقرا الدرس من الكتاب وابعد عن النوت \" مشكلة النوت انه يخلي المادة تافهة وبسيطة \"\n2- ابحث عن شروح للدرس في اليوتيوب وحل الامثلة وحاول تنوع مصادر الفهم … لاتخلي الدكتور هو المصدر الوحيد… عندك اليوتيوب والمواقع ودروس الماث 002 موجودة بالنت زي الرز\n3- بعد ماتسوي اللي فوق كل بعد كلاس ماث … هنا يجي دور الشغل الحقيقي بالويكند :\nبالويكند حل جميع اسئلة الكتاب وحاول تخلص كل اسئلة التشابتر اللي بالاسبوع واحتفظ باوراق حلولك ودبسها عشان ترجع لها بالكويز ثم بالميجر ثم بالفاينل\n4- بالكويزات رح يكون عندك اوراق حلولك لاسئلة الكتاب ورح تذاكرها مضبوط ومايحتاج منك الكويز اكثر من كذا\n5- الميجر يبي لك بس تشوف الاولد اقزام وتراجع جميع اسئلة الكتاب وتحلها بسرعه بحيث تختبر سرعتك\n6- لو كنت تبي A+ لا تعتمد على كتابك فقط وانما هناك كتب اخرى لنفس دروسك تقدر تشوف الاسئلة منها وتحلها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-help-me-please/171417/11", "user": "Edencian", "ts": 1452116861000, "tid": 171417, "pn": 11}}', 1452116861000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420222-math002', 'stk-osama16', 'MATH 002', 'info', '{"desc": "كنت عنده ماث 002 ترم 132\n\nميجر 1 & 2 كلهم 11 والكويزات كلها 5 وتحت\n\nكلاس تست 1 جبت فيه 1.5 والثاني 3 من 4 …\n\nاعطاني في الكلاس وورك 11 من 16 مع الهوموركات 18 من 24\n\nكان باقي لي 20 على النجاح وجبت 24 بالفاينل الحمدلله … عموما سهالات بإذن الله\n\nباقي لك كلاس تست 2 وشد حيلك فيه والفاينل جب فيه فوق 20 وبإذن الله ناجح", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/168099/16", "user": "Osama16", "ts": 1418465970000, "tid": 168099, "pn": 16}}', 1418465970000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p238748-math002', 'stk-_116', 'MATH 002', 'info', '{"desc": "السلام عليكم شباب\nأنا حاط لكم اليوم هذا الموضوع حق تريح قلبك وتفضفض وانا اول واحد راح أبدأ.\nانا قاعد على احر من الجمر استنى نتايج ماث\n002 والله يستر , انا مجموعي 43 لكني في الفاينل أسئلة سهلة كثيرة ماحليتها وقت الاختبار ما ادري ليش وبعد الاختبار لما اذكرها اقول صج اني غبي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/61047/1", "user": "_116", "ts": 1201117592000, "tid": 61047, "pn": 1}}', 1201117592000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p680546-math002', 'stk-user6854', 'MATH 002', 'info', '{"desc": "بسمهِ تعالى\n\nتم وضع حل الاختبار في صفحة الـ PYP Math ، و مكتوب إن الدرجات موجودة إلا أنه عند تجربتي الدخول لم أجد سوى درجات الميجر الأول\n\nعلى أية حال بإمكانكم تحميل الحل ( Solution ) [من هُنا تحميل ]](http://www.kfupm.edu.sa/pypmath/pages/exam002/t093/exam%202%20math2%20answers%20key%20093.pdf)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-solutions-for-math-002-exam-2/93327/1", "user": "user6854", "ts": 1281486035000, "tid": 93327, "pn": 1}}', 1281486035000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p784628-math002', 'stk-stories', 'MATH 002', 'info', '{"desc": "السلام عليكم\nصباح/مساء الخير\nأممم…عزيزي\nهذا المدرس درسني ماث 002 ورأيي فيه مدرس فاهم المادة وخلال الدراسة معاه واجهت مشكلتي القديمة وهي البطء في الكتابة لأن النوت عنده مفيد وهو يكتب ما شاء الله, نصيحتي لك ركز وياه و بعد ما تأخذ الدرس اليوم تروح في الغرفة وتفتح وش أخذت هذا اليوم وحل الهمورك المتعلق بدرس اليوم يعني سؤال أو أكثر ترتااااااح وتستفيد جداا نصيحة من قلب يا خوي\nوبالنسبة للساعات المكتبية “أوفس أور” أي سؤال أو شيء مو فاهم روح عنده وبقووووه… قدااااام\nوكذلك يمكنك مراجعته بالنسبة لأسئلة المياجر القديمة … لاتتردد في السؤال عن أي صغيرة أو كبيرة هذا حقك وأنت جيت علشان تتعلم\nوتراه متساعد إن شاء الله\nفي النهاية ترى+a من نتاج يدك وتعبك وتوفيق الباري وأما الكتاب والمعلم والنوت…واجب… عبارة عن وسائل وليس الغاية\nويقولون \" مثل ما تبي تأخذ لازم تعطي\"\nوأحب أقولك كلمة \" ترى أنت شيء\"\nوالله ينور دربك بالتوفيق لك ولباقي الشباب\n…\nرأي شخصي…واعذرني على التقصير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/102348/5", "user": "stories", "ts": 1297230078000, "tid": 102348, "pn": 5}}', 1297230078000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840812-math002', 'stk-g00dman', 'MATH 002', 'info', '{"desc": "الافرج يخووي كان حول 13 … لكن الاختبار كان من صعب إلى متوسط … و كان أبسط من الأولد إكسام… و أختبار 092 كان الافرج حول الـ 10 .\n\nفي نقطة ثانية السمسترات الماضية ( 092 و 093 و 101 ) كان الفاينال جدا بسيط وممكن أقول عنو تافه للي مذاكر … سمستر 092 أنا ماختبترته … لكن روميتي إختبره و كان جايب العيد في ميجر 2 ( 8 من 22 ) لكن جاب في الفاينال 29 من 36 … وسمستر 093 انا جبت العيد في المياجر كلها لكن جبت 28 في الفاينال … و جبت d+ … أخذته في السمستر اللي بعده … و جبت في الفاينال 25 .\n\nفا شدو حيلكم يا إخوان … لا تيأسوا ترا والله إذا حطيت في راسك إنك مارح تعدي … صدقني مارح تعدي لو يسير اللي يسير … من الان حط في راسك تجيب أعلى درجة تقدر تجيبها … و حاول لا تفوتك ولا درجة … و لعلمكم مابافي إلا 4 أسابيع … أفرغ جميع طاقاتك فيها … في كل المواد … و في النهااية انت الربحان … مارح تخسر أي شيء … حتعدي و حترتاح من الهموم\n\nو ان شاء الله غير كذا الدرجات تكون حلوة في هذا الميجر\n\nالله يكون في عونكم ياشباب … و نصيحة مني و من واقع تجربة … لا تيأس لا تيأس لا تيأس\n\nموفقين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-major-2-hell/107192/27", "user": "G00DMAN", "ts": 1304615106000, "tid": 107192, "pn": 27}}', 1304615106000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1383122-math002', 'stk-amore772', 'MATH 002', 'info', '{"desc": "اسمع ي حبيبي ي محمد\n\nالوقت لكل سؤال هو عبارة عن 5 دقائق لكن بعض الاسئلة تحلها في دقيقتين والبعض يحتاج الى 8 دقائق واكثر(من وجهة نظري)\n\nوطبعا تختلف القدرات للاختلاف الاشخاص\n\nطبعا توجد اسئلة عندما تحلها اول مرة تاخذ وقت لكن مع الممارسة تشوف انك تحلها بسرعة\n\nومافي شي صعب بالجامعة ذي طالما انت اولا مهتم بعبادتك وصلواتك\n\nومهتم بدراستك تذاكر اول بأول\n\nصدقني راح يجي الميجر وانت مرتاح له\n\nطبعا يمكنك المراجعة والتاكد من جميع الاسئلة\n\nوالله يوفقك الترم الجاي\n\nدعواتك لنا ^^", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/163083/8", "user": "amore772", "ts": 1403915142000, "tid": 163083, "pn": 8}}', 1403915142000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378149-math002', 'stk-ageel-16', 'MATH 002', 'info', '{"desc": "المدرس ممتاز جداً روميتي كان عنده … شرحه جداً ممتاز والكويزز صعبة عشان الوقت ١٠ دقايق … دايماً يكون في سوال مستحيل … والافرج يكون عنده ٢ … اتـذكر روميتي جاب في كويزاته ٢ ، ٦ ، ٥ ، ٥ ،٣ ،٨ … ، والكلاس تيستس ٢.٩ , 2.1 … طبعاً الدرجات تقريبية … وافرج كلاسهم كان مو مرة عالي … اخذ كلاس وورك ١٥/١٦\n\nاهم شي لا تضيع الكويزز … ذاكر شرحه السبورة … والريسايتشنز … وصدقني بتجيب اقل شي ٥ في الكويزز…\n\nالله يوفقك ويسهل لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/162405/4", "user": "Ageel-16", "ts": 1402178151000, "tid": 162405, "pn": 4}}', 1402178151000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1168813-math002', 'stk-ngup2011', 'MATH 002', 'info', '{"desc": "**خذ الكلام مني انا مجربه في 002 وطلعت بجـaــريد **\nاول شي المدرس فاهم جدا وعنده طرق خرافيه في حل المسائل لكن عيوبه : انه جديد ماله سنتين & اسلوبه في الشرح وطريقة في توصيل المعلومه & وشرحه ع السبورة ملخبط شوي\nالمهم :\nكويزاته سهله جدا سؤال واحد او سؤالين بس والوقت كافي\nطبعا ما عنده نوته ع ايامنا ويشرح امثلة واسئلة الكتاب لكن الكويزات من الاولد قزامز يجيبها\nالكلاس ورك يشوف في نهاية السمستر الطلاب اللي مالهم امل في النجاح ما يزودهم ويزود باقي الطلااب ( انا اخذت كلاس ورك كامل ) + يمكن يسوي لك بونوز اذا جبت في المياجر كامل او 19 18\nما انصحك تكتب نوت معاه ودايما اذا ما فهمت اسأله وراح تفهم حتى لو بالاوفيس اور\nانت بتستفيد من شرحه ولو الشي البسيط لكن اقولها لك شد ع نفسك وذاكر الافضل لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/138769/16", "user": "NGUp2011", "ts": 1359062279000, "tid": 138769, "pn": 16}}', 1359062279000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1315027-math002', 'stk-bomana3', 'MATH 002', 'info', '{"desc": "يعطيك العافية اخوي\n\nبالنسبة للي يقولون لا تفوت عليك الكورس\n\nبالنسبة لي اجتياز اختبار البروموشن يعني فهم الطالب للكورس بدون الحاجة الى شرح من الدكتور\n\nيعني ما بكون فوته\nبكون فهمته بمجهودي\n\nطبعا هذا اذا عديته 🤠\n\nاهم شي حاليا ابي اتأكد اذا فيه احتمال ما يسوون اختبار هالسنة عشان ما تروح مذاكرتي على الفاضي\n\nوهل يحتاج اني اسجل عشان ما يفوتني الاختبار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/154881/15", "user": "BoMana3", "ts": 1388865000000, "tid": 154881, "pn": 15}}', 1388865000000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p871051-math002', 'stk-user7721', 'MATH 002', 'info', '{"desc": "عندي مداخله :\n\nاول شي فكرة السنه التحضيريه شي مهم يعني انت تبي تطلع للجبل وتبي تعرف كل الانظمه بس كيف\nوانت ماعندك اساسا\nالتحضيريه وضعت عشان توجدلك هالشي هذا\n\nثاني شي فكرة الدرجات كلنا متفقين انه مافي اساس لها ولا شي ثابت يعني السنه الماضيه ستاندر فيزيا 40\nهالسنه 45 ،، ماث 002 افرجها 65 وهالشي مو معقول بنظري اذا على كذا خولها ستاندر 60 والطالب يعرف وش له ووش عليه\nالانجليزي اغبى مادة بالتحضيريه لانه نظامها غبي ،، ممكن تطيح بمدرس فاشل وتشتكي عليه ويضل ع ماهو وترسب وهذا اللي صار فيني وخسف فيني بالكلاس وورك بس مانقول غير الحمد لله ،، المناهج ماهي واضحه اشياء نشوفها خذنها بمتوسط نرجع ناخذ نفسها بس عبط وتضيع وقت ،، اربع ساعات باليوم كثيره بهالماده\nيعني لو مخلي الماث زي نظام الصيفي كان افضل يعني ويسحبو عدد كلاسات من الانجليزي\n\nاخر شي انا لاحظت للاسف بالفترة الاخيره ان الجامعه تبغى من كل طالب انه يدرس باليوم بمعدل ساعتين\nلازياده ولانقصان ،، واكاد اجزم انها كافيه ،، وماتدخل فاينل او ميجر الا تفتح اولد اكزامز تقزر عليها بس عشان ترضي ضميرك\n\nللأوريات الجدد نصيحة طالب مجرب ونصيحة طلاب جبل ،، حل هوم وركك بنفسك ولا تاخذه من احد ثاني\nوذاكر ساعتين باليوم وامورك بالسليم وصدقني بترتاح وبتطلع وبتتونس وكل شي بيكون زي الحلاوه\n\nموفقين يارب واشكر اللي طرح الموضوع\nتحياتي لكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/90138/55", "user": "user7721", "ts": 1310869928000, "tid": 90138, "pn": 55}}', 1310869928000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p923520-math002', 'stk-algnnas', 'MATH 002', 'info', '{"desc": "اولا الاختبار احس مو ذاك الصعوبه اعتقد الافرج 14 الشي الثاني للي ماخذ 16 وزعلان شف الي راد تحتك جايب 6 ويحمد ربه والي جايب 6 تقدر تعدي يالطيب بالراحه ان شاء اللله لو شديت حيلك وبديت تذاكر للميجر الثاني لو فرضنا جبت 12 بالميجر الثاني و17 كلاس وورك و23 من 36 بالفاينل باذن الله تعدي ولا تياس ابد اما الي يسال عن السوال لا اعتقد حلهم صح والطريقه تقسم الرقم الى رقمين بحيث واحد منها يقبل على 9 ويكون ناتجه زوجي. يعني بيصير ال65 54على 9 و11على 9 تطير الاولى لانها. تصير 6 ما تاثر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002/114225/11", "user": "algnnas", "ts": 1319235916000, "tid": 114225, "pn": 11}}', 1319235916000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p444229-math002', 'stk-sweet_h', 'MATH 002', 'info', '{"desc": "شوف اخوي انا اخذت مع بالعربي والله انه اسسني احلا اساس بالماث وكنت اسلم هوم وركات والكويزات عادية وغياباتي كانت 8 شوف انت انشب له بالاوفيس اور تراه يدف فيه دف مب صااااحي وبالاخير عطاني 9 من 10 على النظام القديم لما كان الكلاس ورك من 10 يعني اضمن الكلاس وورك ووركز على شرحه زين تراه فنااااان بالشرح وشد حيلك وبتعدي وان صابت صابت وعندك فرصة السمستر الجاي وكذا تكون فهمت المادة لو خذيتها السمستر الجاي وتمشي سلام سلام وترا ما بقى شي على الصيفي كمل معاه وشد حيلك بالميجر الثاني والله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002-major-1/76367/4", "user": "sweet_H", "ts": 1249822435000, "tid": 76367, "pn": 4}}', 1249822435000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p409425-math002', 'stk-s200810xxx', 'MATH 002', 'info', '{"desc": "صراحة … استاذ في قمة الروعة والأحترام\nواكثر شيء يضايقه لما طالب يجيب صفر في الكويز عنده او\nطالب مايحل زين في المايجر\nوعنده مصلحة الطالب فوق كل شيء … وهو مستعد يضيع حصه كاملة\nفي التوعية بس علشان الطلاب يذاكروا و يجتهدوا\n… وعيبه الوحيد\nهو انه بخيل في الدرجات\nولكن في نهاية السمستر بيضها كل واحد دفه بكم درجة مجانيةمن ثلاث الى اربع\n…\nوكل الشكر لكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math002/73707/14", "user": "s200810xxx", "ts": 1243963766000, "tid": 73707, "pn": 14}}', 1243963766000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p145353-math002', 'stk-user1662', 'MATH 002', 'info', '{"desc": "انا اخذت ماث 002 في الصيف وكنت مو مهتم وجبت الاختبار الاول 7 من 22\nوبعدها قمت احل اسئلة الكتاب اغلبها تقريبا بس عدد كبير يعني وعديت بـ C\nوهذا طبعا بدون الاختبارات القديمة\n\nفانت حل اللي تقدر عليه من اسئلة الهوم ورك والريسايتشن واختبارات قديمة والباقي على ربك\n\nهذا اللي اقدر افيدك فيه\nوتقبل خالص تحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/help-me-please-2/54343/3", "user": "user1662", "ts": 1168721451000, "tid": 54343, "pn": 3}}', 1168721451000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1315094-math002', 'stk-thedebater', 'MATH 002', 'info', '{"desc": "إذا كان قصدك من مواد السنة التحضيرية فتقدر تنزل مع الفيزكس مادة وحدة بس إما إنجليش أو ماث\n( أما بخصوص باقي المواد مثل الستدي سكلز والكمبيوتر والوورك شوب فما عندي فكرة وما أتوقع أصلاً أحد ما يعديهم )\nيعني مثلاً لو كان عندك إنجليش 04 وماث 002 وفيزكس 001 … تقدر تنزل في الصيف إما فيزكس وماث أو فيزكس وإنجليش لكن ما تقدر تنزل الماث والإنجلش مع بعض…\nووضعك في السنة الجديدة راح يكون تكملة للمادة اللي ما درستها في الصيف.\nراح تكون طريقة دراسة السنة الجديدة كالتالي :\nالفصل الدراسي الأول راح تدرس المادة المتبقية … لو كانت ماث فبتبقى تدرسه طول السمستر ولازم تعديه أو تنطرد … أما لو كانت مادة السنة الجديدة هي إنجليش راح تدرس انجليش مدة الكورس بس بالإضافة إلى مادة إجبارية من الجبل إما عربي أو إسلامي … لو صار وعديت الكورس فبتبقى تداوم بس حق كورس الجبل في الوقت المتبقي من الفصل الدراسي الأول اللي هو ساعتين في الأسبوع.\nأما الفصل الدراسي الثاني فتروح وتبتدي دراستك الجامعية …\n\nــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــ هذا في حال انك تبي تنزل مواد السنة التحضيرية اللي ما خلصتها في الصيف\n\nلكن لو خلصت كل مواد السنة التحضيرية ما عدا الفيزكس وتبي تنزل مواد من الجبل فبصراحة ما عندي فكرة كاملة عن الموضوع وما أبي أقول لك كلام احتمال يكون خطأ\n\nأتمنى إني جاوبت عن سؤالك\nوالأهم انك فهمت هالطلاسم :d\n\nأتمنى لك التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/154913/4", "user": "TheDebater", "ts": 1388870444000, "tid": 154913, "pn": 4}}', 1388870444000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p858139-math002', 'stk-ahmadonline', 'MATH 002', 'info', '{"desc": "اخوي انا اخذت الماث 002 لاول مره في الصيف … وبصراحه انصحك تاخذه وبقوه وحتى لو مع الـ pe\n\nالماده مره حلوه يعني مو زي الـ 001 … بتشوفها شوي حلوه لان اغلب القوانين بكل التشابتر بتكرر … يعني من الاخير\n\nالماده مره حلوه وانصحك انك تاخذها … لان اذكر بعد يوم اخذتها في الصيف كانوا يسهلون الاختبارات اسهل من السمستر العادي …\n\nواخر شي طلعت بقريد b … عشان الفاينل ما ذاكرت له تمام لان تعرف اخر يوم وصيف وكذا … بس لو شديت كنت اقدر اجيب b+ بالراحه …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/108578/66", "user": "ahmadonline", "ts": 1308871457000, "tid": 108578, "pn": 66}}', 1308871457000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p584236-math002', 'stk-moataz', 'MATH 002', 'info', '{"desc": "السلام عليكم،\n\nاهلاً بالشباب، تحديداً من اخفق في اختبار الامس:)\n\nبعد قراءتي لردود فعل الطلاب، قررت وضع هذا الموضوع اللي راح اشرح فيه وجهة نظري بخصوص\nهذا الاختبار … والهدف هو ان نخرج بنتيجة تساعدنا في الاختبارات القادمة بدلاً من التذمر الذي\nلا يفيد . وان شاء الله الكل راح يكون ناجح 🤴\n\nطبعا انا وجهة نظري ببساطة تتلخص في الامور التالية:\n\n- الاختبار لم يكن من خارج الكتاب اطلاقاً.\n- الاختبار كان يحتاج مجهود عالي جداً في المذاكرة (حل تمارين الكتاب كلها ).لأن بعض الاسئلة تحتوي فكرة سؤالين\nاو ثلاثة في سؤال واحد.\n- الاختبار كان محتاج سرعة عالية في تذكر الحقائق الرياضية وهذي ماتجي الا بتنفيذ النقطة السابقة]\n- بالرغم من ان الوقت يعتبره البعض ضيق، الا اني اخالف ذلك الرأي. مشكلة الوقت تتمثل\nفي عدم تنظيمك له، بمعنى ان الاختبار يحتوي على اسئلة من مستويات مختلفة\nسهل - متوسط - صعب … فبعض الاحيان يضيع الطالب الوقت في السؤال السهل ولايجد بعد ذلك\nوقت للتفكير في السؤال الصعب وماراح تتفادى ذلك الا بالتعود على حل الاسئلة السهلة بسرعة\n(الحل بالرجوع للكتاب ايضاً ! )\n- الخوف من الاختبار والرهبة المتوارثة عبر الاجيال هي اكبر سبب يعيق الطالب من استرجاع\nما استذكر. لذلك يجب علينا فعل امرين:\n+التعوّد على جو الاختبار ( يعني بين كل فترة وفترة جرب حل لك ميجر قديم بحيث يكون لك ساعتين\nفقط لحل الاسئلة ) << اسلوب معروف\n+ عدم الاستماع لكلام واراء الغير … لأن عادة من يتكلم كثيراً هو من لديه هموم تجاه المادة ولا يعرف كيفية\nتجاوزها … او ربما لا يريد تجاوزها (مافيه همة عالية )\n- بفرض ان البعض ليست لديه ميول رياضية ابداً … فمو مشكلة اذا اخطأ في الاسئلة المركبة من اكثر من فكرة\nولكن المشكلة هي ان اخطأ في الاسئلة الغير مركبة\n- الاختبار صمم للتمييز بين الطالب المجتهد جدا والمجتهد والغير مجتهد وليس للتمييز بين الذكي\nوالغير ذكي.\n- الاختبار لم يكن مصمم لتعقيد الطالب ولكن للتمييز فقط … واللي له باع مع اسئلة الاولمبيادات\nالعالمية راح يفهم وش اقصد بالضبط.\n- ميجر 002 اسهل من 001 … ولكن الاول يحتاج مجهود اكثر بكثير من الثاني !\n\n--------------------\n\nوبما اني اعرف ان البعض راح (يفش خلقه) علي لأنه خبص …\nفحبيت اضع هذا فهرس يربط السؤال مع طريقة حله في الكتاب للتوضيح بشكل اكبر\n\nانظر لصفحةالحلول\n\nhttp://www.kfupm.edu.sa/pypmath/pages/exam002/T092/Math002_e1_092.pdf\n\n1- صفحة431 سؤال 97-98\n2- صفحة428 سؤال 33-40\n3- صفحة442 سؤال 38\n4- صفحة442 سؤال 13+16+17\n5- صفحة444 سؤال 71-80 ولكن بدمجها مع افكار 001 ونظرية change-of-base\n6- اساسيات اللوغاريتم + صفحة444 سؤال 87 + فكرة 50 = 100/2\n7- صفحة 465 سؤال 53 + فكرة من 001\n8- اساسيات اللوغاريتم والاسس فقط\n9- صفحة 509\n10- سؤال سهل جدا (درس الزوايا)\n11- صفحة 501 سؤال 69-88 (سهل جداً ولايحتاج حل )\n12-اساسيات الدوائر المثلثية فصل 5.2 + صفحة 509\n13- اساسيات حساب الدوائر المثلثية (سهل)\n14- صفحة 537 (فكرة عادية)\n15- نفس السؤال السابق\n16- صفحة561 قاعدة ARC LENGTH\n17- اساسيات الدوائر المثلثية - راجع شكل3 صفحة 561 + THE COTERMINAL ANGELS\n18- فصل 6.1 (امثلة متعددة والفكرة سهلة)\n19- فصل 6.3 صفحة 591 (مثال 4 (سؤال سهل))\n20- نفس السابق\n21- نفس السابق\n22- نفس السابق\n\nالان احب اضع الوصفة السحرية للنجاح 👍 وهي من مدرسي:\n\n1- ابدأ بمذاكرة نوت مدرسك او اي نوت تحس انه ممتاز\n2- حل اسئلة الكتاب ((( كلها )))\n3- بعد ذلك انتقل للاسئلة الخارجية ( اولد اكزامز، كويزات، سواء لمدرسك او لمدرس ثاني)\n\nطبعا انت راح تبدأ بدراسة النوت عشان تفهم الافكار … وراح تروح للكتاب عشان تعرف كيف\nتطبق اللي فهمته (مسألة مهمة - فهم بدون تطبيق = لا شي !)\nبعد ذلك راح تروح على الاسئلة الخارجية عشان تدخلك جو الاختبار وتتعرف على بعض الخدع اللي ممكن\nتواجهك\n\nختاماً … اتمنى تكون الردود واقعية … ويكون النقاش مثمر …\n\nانا مستعد للاجابة على اي سؤال جاد … واتمنى ماتضعوني عدو لكم … تروني خبصت 😆\n\nلكن مع ذلك، فضلت انظر للاختبار نظرة واقعية، لتجنب الاخطاء في الميجر اكزام الجاي (17 مايو 😏 )\n\nبالتوفيق للجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/86602/1", "user": "Moataz", "ts": 1270573549000, "tid": 86602, "pn": 1}}', 1270573549000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p584267-math002', 'stk-user6200', 'MATH 002', 'info', '{"desc": "صعب مو معناه مستحيل كل سنة يجي اختبار صعب 002 مافيها شي جديد!!!\n\nاللي مذاكر زين وحال جميع اسئلة الكتاب راح يبدع!!\n\nواذا انت او غيرك ماعنده مقدرة على المذاكرة فالباب حق الجامعه يفوت جمل!!!\n\nوالرجال جزاه الله خييير ينصحكم ويوضح لكم وماقصر وهذي راح تفيدكم بالجبل (كل افكار الاختبار موجوده بالكتاب بس لازم تحل تمارين كافية وبسرعه عشان الوقت)\n\nانت طالب جامعه لازم تذاكر وتجتهد اذا كنت تبي قريد افضل من غيرك لكل مجتهد نصيب هذي سنة الحياة!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/86602/7", "user": "user6200", "ts": 1270576184000, "tid": 86602, "pn": 7}}', 1270576184000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p584500-math002', 'stk-user5812', 'MATH 002', 'info', '{"desc": "الميجر كان صعب\nمو كأفكار بالعكس كوقت وكطول أسئلة\nيعني الحمدلله كل سؤآل من الميجر عارف طريقة حله\nما عدا سؤآل واحد اللي هوا حق البكرتين\nاغلاطي كلها غبية يا اشارات يا نسيت انطق مقام\n\nوبالنسبة لطريقة المذاكرة :\nشوف انا ما اذاكر صراحة\n\nاحل الهوموركات كلها\n\nلكن مذاكرة لمجرد المذاكرة ما اسويها\n\nقبل الميجر ب٤ ايام ادفرها\n\nوخلاص\n\nالحمدلله درجاتي زينة مرة\n\nيعني ما انزل عن b+\n\nلكن\n\nاني اطبق طريقتك في المذاكرة\n\nاشوفها مستحيلة بالنسبة لي\n\nيعني انا متعود على طريقة المذاكرة هذي طول حياتي\n\nلكن شكلي حغيرها والله\n\nالميجر الجاي\n\nبإذن الله ٢٢ من ٢٢\n\nوانا قدها وقدود ان شاء الله\n\nهمسة : انت تدرس عند الشرقاوي صح ؟\nتخمين من الوصفة المذكورة للنجاح\nدايم اسمع الشرقاوي يقولها 🌹\n\nبالتوفيق عزيزي وشكرا على الموضوع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/86602/16", "user": "user5812", "ts": 1270591137000, "tid": 86602, "pn": 16}}', 1270591137000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1382049-math002', 'stk-madridista', 'MATH 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته …\n\nبما ان الميجر قرب يا طلاب 002، ماحبيت أبقي الفائدة لي بس… حتى لما قلت أخلص مذاكرتي وأنزلها لهم، ماقدرت… ماش قلبي طيب 😆 طبعاً الملفات هذه من تجميعي فقط ( يعني جمعت الروابط اللي نزلوها الطلاب في في موضوع واحد )\n\nالـ Recitation\n\nترم 132: https://www.dropbox.com/s/cbm6qrkiks4zsng/math002%20recitations.rar (بدون الحلول)\n\nhttps://www.dropbox.com/s/ar9ivs9xhm9umfi/math002%20recitations%20with%20solutions.rar (مع الحلول)\n\nترم 133:\n\nراح تحصلونها كلها مع حلولها بصفحة الدكتور سيد عمر ، هنا:\n\nhttp://faculty.kfupm.edu.sa/pyp/syedomar/Math%20002%20Quizzes.htm\n\nالـ manual solutions\n\nاللي هي حلول الكتاب كامل مع خطوات الحل.\n\nhttp://www.4shared.com/file/mszBs7eS/Solutions_Manual_for_Algebra__.html\n\nالـ Notes\n\nبصراحه أنا انصح بشكل كبير بالنوته هذي، افادتني كثير…\n\nhttps://www.dropbox.com/s/zhnq1s3cy5e67a5/math002%20notes%20without%20solutions%20one%20file.pdf (بدون حلول)\n\nhttps://www.dropbox.com/s/a78e7h4kaqwdb0d/Math002%20notes%20one%20file.pdf (مع الحلول)\n\nهذي نوتة أبوجيا (كثير يمدحونها برضو)\n\nhttp://www.mediafire.com/download/e2s88zdhc1ocq3j/Abujiya+Math+002.zip\n\nتذكير: الملفات ليست من صنعي ولا من إعدادي، أنا نسخت الروابط من كذا موضوع وجمعتها هنا…\n\nبالتوفيق للجميع وفالكم الـ A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-recitation-manual-solutions-notes/162966/1", "user": "Madridista", "ts": 1403545669000, "tid": 162966, "pn": 1}}', 1403545669000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p609515-math002', 'stk-user6687', 'MATH 002', 'info', '{"desc": "كلام سليم الين الميجر الثاني\nترا الميجر ماكان تعجيزي مرة وانا اخوك في ناس ماخدين فل مارك\nبس الاختبار وانا اخوك فرق المستويات\nالي كانو مهايطين في الاختبارت السهلة اخذ على راصو في الميجر الي فات\nاو الاختبار صحيح انه شبه خالي من الاسئلة المباشرة بس في اسئلة تنحل على 3 دقايق وتستفيد من الوقت للاسئلة الصعبة على قولتك\nاوو ستنادر الماث على كلام الوشاويش انو شبه ملغي 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-02/88195/48", "user": "user6687", "ts": 1274125929000, "tid": 88195, "pn": 48}}', 1274125929000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1243177-math002', 'stk-bahatab', 'MATH 002', 'info', '{"desc": "في حالتين:\n1/ إنك ما أخذت ماث002 من قبل وفي هذه الحالة بإمكانك أن تأخذ حتى 13 ساعة مضمونة معها الماث بشرط أن تكون منهي متطلبات مواد الجبل اللي ناوي تاخذها\nفمثلا: الكميستري 101 يحتاج إنك تخلص الفيزيكال ساينس, الفيزياء يحتلج إنك تخلص الفيزيكال ساينس ونفس الوقت تاخذ ماث 101 أو مخلصه\nوعلى كلامك أعتقد المواد اللي بإمكانك تأخذها الكيمياء , انجلش 101 , عربي 101 , اسلامي 111\nوان انت ما تواجه صعوبات في الماث يعني بامكانك الحصول على b+ وأعلى بسهولة رأيي انك تأخذ الانجلش والكيمياء وان فيك همة عربي أو اسلامي تكمل 13 ساعة وبالاخص الكيمياء لو تخلصها بدري ترتاح\n\n2/ إنك أخذت ماث002 من قبل والان تعيدها في هذه الحالة نظام الجامعة لايسمح لك بتنزيل مواد من الجبل لاعطائك الفرصة للتركيز على اجتياز السنة التحضيرية (مع إنه يعطيهم وقت فراغ أحيانا يجعل المذاكرة جدا مملة , تاثيره عكسي احيانا)\n\nهذا الكلام من سنتين تقريبا وما اعتقد غيروه وكمان عشان تسجل من الجبل لازم تروح مبنى 10 يوم التسجيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/146864/13", "user": "Bahatab", "ts": 1373169956000, "tid": 146864, "pn": 13}}', 1373169956000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p995516-math002', 'stk-user1508', 'MATH 002', 'info', '{"desc": "( بما اني قريدر سابق للماث + مواد ثانيه ) … فيه عدة حالات:\n\n1- بعض الاحيان يكون السلوشن نفسه غلط أو من نسخه قديمه … و الشعب ينقل و لا يدري عن السؤال أصلا … فتكون المحصله انه ياخذ صفر على هذا السؤال\n2- بعض الاحيان يكون الهوم وورك ما له سلوشن ( من برى الكتاب ) … و يبدأ الطلاب بالاجتهاد بالحل … و اللي ما وده يشتغل ينقل من الطلاب الثانين سواء ً حلهم صح أو خطأ … و بهذي الحاله يكون اصطياد الغشاشين سهل جدا … و على حسب القريدر قد يعطيهم أصفار أو يوجه تحذير\n3- خذ مني هالمعلومه … أغلب المصححين يفضلون يصححون للطلاب اللي ناقلين من السلوشن … ليه ؟ لانه أسهل له بالتصحيح و لا يقعد 10 دقايق او ربع ساعه على كل سؤال علشان يتتبع خطوات الحل و يتأكد من كل رقم … خصوصا اذا كان عدد الطلاب كثييير و أسئلة الهوم وورك كثيره\nو انا أبتكلم عن نفسي الحين و بدون مدح … اذا شفت طالب ما نقل من السلوشن و حاول يحله بطريقته … لو كان حله خطأ … أعطيه جزء من الدرجه لانه حاول و اجتهد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002/121347/9", "user": "user1508", "ts": 1330423704000, "tid": 121347, "pn": 9}}', 1330423704000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p916848-math002', 'stk-omar.a', 'MATH 002', 'info', '{"desc": "انا درست عند المدرس القدير الفاضل معاذ ابوجيا سمستر 092 ماث 002\n\nمدرس لا ينسى صراحة اذا قدرت تحل اسئلته فالمياجر بيس اوف كيك\n\nخلصت 4 كورسات ماث وآخذ الخامس الآن ما مر علي مثل ابوجيا\n\nحل الاسئلة اللي في النوت تبعه وفي كلاس تيستس موجودة في التراكر محلولة\n\nواي خدمة انا حاضر …\n\nطبعاً كويزات على ما اذكر انها من النوت تبعه فقط + احيانا يجيب من الريسايتيشن\n\nلكن ابوجيا افضل مدرس موجود في الاوريا في نظري …من ناحية الشرح وطيبة النفس\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/113585/5", "user": "Omar.a", "ts": 1318286121000, "tid": 113585, "pn": 5}}', 1318286121000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p418772-math002', 'stk-user5025', 'MATH 002', 'info', '{"desc": "في روايتين\n\nالأوله يقلون انه قال\nحنى جبنى اسئلة صعبه علشان انه حنى ما نقدر نفارقكم كلكم فاضروري في ناس تصيف ويانا\n\nوالأخرى يقلون انه قال\nالي رسب في 001 وعده وصار يقدر ياخذ 002 او الي رسب في 002\nراح تنزل لهم المادة دايركتلي في الصيف بس اذا كان رسب في الأنغلش بعد فما راح تنزل دايركتلي ضروري انت تسجل بنفسك\n\nوقال بعد انه الدرجات بتنزل بلكثير يوم الأحد واحتمال تنزل قبل\n\nوبنسبة لمستوى الأختبار انا اشوفه انه متوسط مأئل اله الف والدوران\n\n.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-math-002/74423/24", "user": "user5025", "ts": 1245778583000, "tid": 74423, "pn": 24}}', 1245778583000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1434597-math002', 'stk-user9893', 'MATH 002', 'info', '{"desc": "انصحك بالكيمياء بس ترا يبغالها متابعة أول بأول, chem101 هي عبارة عن أساسيات الكيمياء ,تقريبا نفس اللي كنا ناخذه في الثانوي,\n\nو صراحة ما ودي احطمك لكن الضغط بيجيك كذا ولا كذا , فانت بيدك أنك تقلل منه وتنزل كيمياء وتفتك . وبالنسبة للمذاكر لازم اسبوعيا , وانا ادري أن math 002 صعب\n\nلكن صدقني math002 +chem101 أسهل من math10X+chem101+ics103 أوmath10X+chem101+phys10X .\n\nو إذا كنت كيمكال بتنزل ch102 في الفرشمان وهذا يزيد من الصعوبة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170988/7", "user": "user9893", "ts": 1448538214000, "tid": 170988, "pn": 7}}', 1448538214000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840731-math002', 'stk-king7gold', 'MATH 002', 'info', '{"desc": "بالنسبة لي ذاكرت أولد اقزامز وكانت أفكارها فيها نوع من الصعوبة ولكن في كم سؤال معيّن ، يعني الاختبارات كانت فيها جزء صعب وجزء متوسط وجزء سهل …\n\nولكن هالأختبار ، عن جد ماني متأكد من ولا سؤال إني حليته صح أو لا … بالإضافة إلى “التشويز” …\n\nمع احترامي للي حاط الأسئلة ، لكن مايعرف يقيس صح ، مستوى الأسئلة كان مرررررررررررة صعب …\n\nأتوقع الأفرج 9 من 20", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-major-2-hell/107192/10", "user": "king7gold", "ts": 1304605401000, "tid": 107192, "pn": 10}}', 1304605401000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840733-math002', 'stk-the_marvel', 'MATH 002', 'info', '{"desc": "أجل هذا سبب صعوبة الميجر…\n\nمع إن ميجر 2 دايم يجي أصعب من 1\n\nالآفرج في 092 إن ما كنت واهم 11 أو 12 من 22 بالكثير…\n\nبس أبشركم بفاينل سهل إن شاء الله\n\nذاكروا المنهج اللي بعد ميجر 2 وركزوا عليه\n\nوراجعوا منهج ميجر 1 و2 وتضمنون درجة عالية إن شاء الله\n\nلأن الفاينل غالبا مباشر…فـ لا تتحطمون\n\n002 طويل وهذا اللي يخليه صعب أحيانا\n\nفـ ذاكروا مبكرين للاختبار النهائي\n\nموفقين جميعا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-major-2-hell/107192/12", "user": "The_Marvel", "ts": 1304605542000, "tid": 107192, "pn": 12}}', 1304605542000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840901-math002', 'stk-user4126', 'MATH 002', 'info', '{"desc": "الااختبباار طبيعي يجي صعب مره لانه اول مره اسمع انه افرج الميجر الاول 15 من 20 من دخلت الجامعه طبعا انا دفعة 27 فلازم يصقعونكم بزي هالاختبارات , ولازم تعرف وتتذكر انك في جامعة الفهد مو اي جامعة …\nع العموم يا شباب انتو اديتوا اللي عليكم والياقي على رب العالمين … بالتوفيق … ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-002-major-2-hell/107192/35", "user": "user4126", "ts": 1304628579000, "tid": 107192, "pn": 35}}', 1304628579000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1440074-math002', 'stk-user9306', 'MATH 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nبالنسبة للأنجليزي حاول تتدرب بنفسك مو بس تعتمد على اللي يعطيكم اياه داخل الكلاس\n\nاما بالنسبة للماث 002 فهو مهم جدا لانك راح تستخدمة كثير في الجبل انشاء الله وراح اعطيك ايها من الاخير :-\n\nحاول ترفع تركيزك في الكلاس 200/100(اذا ماقدرت تفهم في الكلاس مالك الا تعتمد على نفسك) +ارجع البيت وابدا من الجديد افهم الكونسبت وحل الامثلة اللي في الكتاب بعدها انتقل الى اسئلة الكاتب وحل قد ماتقدر وشيك حلك ورا الكتاب(الاسئلة الفردية )+ بعدين حل الاولد اقزامز بحيث انك تبدأ تحل سؤال حسب اللى الدرس اللي انت قاعد تذاكر له +وكذا اصل مايحتاج انك تذاكر او تبذل مجهو كبير قبل الميجر او الفاينل لانك اصل انت مذاكر اول باول\nوفالك a+\nاما بالنسبة لتغير الدكتور يفيدونك الاعضاء الباقيين فيها 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/171867/3", "user": "user9306", "ts": 1453384320000, "tid": 171867, "pn": 3}}', 1453384320000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1377236-math002', 'stk-chem22', 'MATH 002', 'info', '{"desc": "وعليكم السلام\nهلا اخوي … بالنسبة للاستاذ حسام الشرقاوي .\nمن افضل اساتذة الرياضيات في الاوريا درسني ماث 002 استاذ فاهم للمادة يشرح لك بطريقة سلسة وبسيطة يفهمها كل طالب وايضا اخلاقه عالية جدا طيب المعاملة جدا جدا ويحاول انك ما تمل في كلاسه واي سؤال تساله ما يتضايق نهائيا ويرحب فيك في الاوفيس اور وجدا متساعد .\nبالنسبة للنوتة اللي كاتبها من افضل النوتات في الاوريا فيها كل افكار وتركات المياجر اللي ممكن تجيك ممكن تكون دسمة شوي بس جدا جدا مفيدة لدرجة انك اذا ذاكرتها ما تحتاج تذاكر اولد اقزام اذا كنت فاهمها صح .\nبالنسبة للكويزات فهي متوسطة عادة وسهلة للي يذاكر لان كل اسئلته من النوتة ولكن بارقام مختلفة وصعبة للي يسحب على النوتة يعني ما يذاكرها كلها لكن يجب عليك تذاكر اول باول واي كويز كن مستعد له اتم استعداد وذاكر النوتة زين وبتجيب قريد مرررة حلو لا يقل عن +b .\nزيادة على كذا هو يشرح الاكسامبلز بعدين يحل اغلب الاكسرسايز اللي في النوتة ويخلي كذا مسالة عشان تتدرب وتشغل مخك واغلب الاسئلة مشابهه للي حلها واي سؤال ما عرفته اساله في الاوفيس اور وما راح يقصر معك.\nوعلى فكرة في الكلاس وورك يزيد بالهبل يعني ياسسك صح ويكرفك عشان تتعلم .\n\nالاستاذ ما اقدر اوفيه حقه صراحة بطلللللل .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/162299/6", "user": "chem22", "ts": 1401912098000, "tid": 162299, "pn": 6}}', 1401912098000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1387346-math002', 'stk-user9305', 'MATH 002', 'info', '{"desc": "23 يمين بالله انها ميب صعبة أبد خصوصاً انك فاهم\n\nفي ماث 002 ميجر 2 كنت جايب 10 والكلاس وورك عطاني 13 والمادة حقت ميجر 2 ما كنت فاهمها كانت مذاكرتي تسليك في تسليك، يوم جاء الفاينل تورطت كان باقي لي 18 درجة على النجاح وعندي ماتيريال ميجر 2 وماتيريال الفاينل اعتبرهن جديدااااااات وكان عندي فوق هذا كله اختبار توفل قريب والمدرس الغانمي كان حاطني مع الناس اللي عندهم احتمال يعدون الكورس، هذي الكلمة “إحتمال” خلتني أحس بإهانة ما حسيت بمثلها في حياتي فقلت للمدرس بيننا الفاينل وحبست نفسي في مكتبة الجامعة وما كنت اطلع منها ألا عشان انام وارجع لها من بكرة حتى الحمد لله يوم طلعت القريدات طلعت جايب c+ فأرسلت رسالة لمدرسي أسأله عن الدرجة اللي جبتها فقال لي انت جايب 30 وأثنى علي بكلام كثير … الشاهد ان الفرصة قائمة لك وترى 23 ميب مستحيلة ابداً وأقدر أقول انها سهلة ما دامك فاهم ترى ترم ثالث في الاوريا شين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/163621/10", "user": "user9305", "ts": 1405890598000, "tid": 163621, "pn": 10}}', 1405890598000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p827647-math002', 'stk-muhannad_ae', 'MATH 002', 'info', '{"desc": "اخي الغالي انا ممن فحط في ماث 002 حتى كدت انقشع من الجامعه قشعة مؤلمة موجعه ولكن تدراكت نفسي وحالتي تشبه حالتك تماما حيث حصلت في الميجر الاول على درجة اكاد اخجل من قولها 😭ولكنني شديت حزامي للميجر الثاني والفاينل وحصلت على مااريد والحمد لله (بالرااااااحه)…مازال المشوار امامك وانصحك بما نصحك به اخي عمر تماما بالحرف الواحد .\nوالله يوفقك في حياتك القادمه واحمل معك دائما شعار (لا يأس مع الحياه ولا حياة مع اليأس)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/105878/8", "user": "muhannad_ae", "ts": 1301430257000, "tid": 105878, "pn": 8}}', 1301430257000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
