) ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p766842-math002', 'stk-al_rashid', 'MATH 002', 'srcP', '{"html": "شباب الي يعرف حل السؤال بالخطوات لا يبخل علينا<br>السؤال رقم 17 في فاينل ترم 093<br><br>​<span data-fid=\"stk-f766842-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f766842-0": {"name": "Math002-093-Final Exam.doc.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/642527d4ea82f4fbe19840b6175a86326aa9dab67430a4b40de23615095338e4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/100977/1", "user": "AL_RASHID", "ts": 1295458960000, "tid": 100977, "pn": 1}}', 1295458960000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p941158-math002', 'stk-user7909', 'MATH 002', 'srcU', '{"html": "هنا سليوشن ماث 002<br><br>تفضلوا من المرفقات<br><br>​<span data-fid=\"stk-f941158-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f941158-0": {"name": "Math002_e2_111.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/28d324a77b1ea8ed3c4b98b57aac17b2cc64da294acb97ae59521c0bb75db3ca"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/116010/1", "user": "user7909", "ts": 1322821839000, "tid": 116010, "pn": 1}}', 1322821839000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8504-math002', 'stk-user8504', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68392", "n": "Dr. Ahmad Al-Zoubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درست عنده ترم 92 math 002\n\nالتحضير : في آخخر الكلاس وبعض الأحياان مايحضر .\n\nالشرح : راح تفهم معه من 40 الى 70 بالميه والبااقي عليك .\n\nالكويزاات :في مستوى صعووبة الاولد اكزاام وكل كويز أكثر من فيرجن وهذي ميــــــــــزته .\n\nالهوومورك : كان عليه 2.5 من درجة الكلاس ورك .\n\nالتقييم العاام B+\n\nوللمعلومية هو مناسب لطلاب السيلف ستدي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p861281-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-zoubi/68392/53", "user": "user8504", "ts": 1309378398000, "tid": 68392, "pn": 53}}]}', 1309378398000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m-awesome-math002', 'stk-m-awesome', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68407", "n": "Dr. Balarabe Yushau", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 002 113\nالتحضير : بداية الكلاس\nطريقة الشرح : يكتب على السبورة وترا النوت تبعه جدا مفيد , حاول تحرص تكتب معه\nالكويزات : متوسطة , يختبرك على مدى فهمك\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\nالصوت: ممتاز\nإضافات : دكتور قمة في الاخلاق , ومتمكن من المادة بشكل عجيب و اذا كنت مركز معه اضمن لك تفهم المادة وتجيب حلو في المياجر , الله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1090872-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/balarabe-yushau/68407/31", "user": "M-Awesome", "ts": 1347381506000, "tid": 68407, "pn": 31}}]}', 1347381506000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jstnawwaf-math002', 'stk-jstnawwaf', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست معه math 002 للترم 142 الساعة 7 صباحا\nأولا كنت مع بلعربي يوشع أفضل أستاذ لـ 001 فحسيت بفرق لمن درست مع إلياس، أول مشكلة واجهتها هي كتابة النوتات معه، ما قدرت أكتب بشكل مناسب، الوقت صراحة ما ساعدني وممكن أكون أبخست الأستاذ حقه، فيه عيب وهو التشاؤم الكبير الذي يبثه على الطلاب من عبارات كـ “الصيف مع البترول أحلى” “كثير ناس بيرسبون” لا تتأثر بهذا الكلام لأن أكثر من واحد أعرفه كان باقي له على النجاح أكثر من ظ¢ظ¥ درجة وجابوا بالراحة، عن نفسي أخذت معه B+، شرحه جيد جدا ويحل أسئلة صعبة واختباراته صعبة وهذا شيء ممتاز، باختصار ركز معه ولا تفكر بالكلام السلبي اللي يقوله وبتأخذ درجات طيبة.\nالتقييم: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434598-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/65", "user": "jstNawwaf", "ts": 1448538326000, "tid": 68415, "pn": 65}}]}', 1448538326000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math002', 'stk-rapls', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172 - Math002\n\nالتحضير : يحضر يوميًا , يسمح بالميك اب مرتين , الاولى عادي والثانية يحطك ليت .\n\nطريقة الشرح : ممتازة جدًا , يشرح بالعربي والانجليزي , أسلوبه جميل , نوتاته حلوة ومختصرة يبدا بأمثلة سهلة بعدين ينتهي بأسئلة بتريكات مختلفة , النوتة جيدة لكن مختصرة وما ينفع تعتمد عليها لحالها , افضّل انك تذاكر معها أي نوتة ثانية تناسبك بالإضافة للريسايتيشن والاولد اقزامز .\n\nالكويزات : متوسطة , 3 أسئلة واحد سهل وواحد وسط وواحد صعب .\n\nالمياجر: كومن .\n\nالفاينلات : كومن .\n\nالقريد النهائي: A+\n\nالصوت: واضح وحتى أكسنته بالانجلش ممتاز , نبرة صوته تتغير وكلاسه ما ينمل .\n\nإضافات : دايمًا ينزل حلول الريسايتيشن والكويزات ع البلاكبورد اول بأول , يوزع اوراق الكويز ويروح ينزل الحل مباشرة وأنت تختبر , يعطي يوم أوف وعادة يخليه خميس بعد ميجر أو بعد اختبارات الانجلش , فكاهي ودايم يضحكنا 😆 😆 , يطقطق كثير واذا جبت درجة ضعيفة ستكون ضحية للطقطقة , ما يقصر بالاوفيس , أنصح فيه 👍 .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498511-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/69", "user": "Rapls", "ts": 1535727145000, "tid": 68415, "pn": 69}}]}', 1535727145000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11914-math002', 'stk-user11914', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002\n192\n\nالتحضير نهاية الكلاس دائما واذا جيت متأخر يرحب فيك بحفاوه واخر الكلاس يحضر بالرقم وتقوله انت اذا متأخر\n\nالشرح : يستخدم نوته على السيرفس حقه يعتمد عليها اغلب الوقت وهالوقت قاعد يضيف اسئله جديده تقويك وتفهمك جوانب الدرس…ممتاز\n\nالكويزات متوسطه… او متدرجه ٣ اسئله سهل ومتوسط وصعب\n\nالمياجر والكويزات كومن\nالصوت: ممتاز\n\nاضافه بسيطه\nشوي الخط عنه حفله…يعني اسبوعين تتعود عليه\nمن شيوخ الماث لايفوتك…يرحب فيك بالاوفس اور\n… مهما كان فلاوي على سماجته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1523185-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/71", "user": "user11914", "ts": 1592504117000, "tid": 68415, "pn": 71}}]}', 1592504117000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rs83-math002', 'stk-rs83', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 T222\nالتحضير: التحضير صار عن طريق برنامج وتصور الباركود ومرات ياخذه بالبداية مرات بنص المحاضرة ومرات بالنهاية.\n\nطريقة الشرح: اسوء شرح بالدنيا. يستخدم سلايداته المختصرة ويخلصلك درس بربع ساعة. اسرع شرح ممكن تشوفه وتسليك مب طبيعي. الدكتور سابق السيلبس باسابيع. تساله يتنرفز و١٠٠٪؜ بيذب عليك ويحسسك انك غبي. الشرح سريييييع حرفيًا كل كلاس يخلص درس ونص ومرات يقفل على درسين.\n\nالكويزات: سهلة مرا الصراحة نفس مستوى الاولدات\nالمياجر: مشتركة\nالفاينلات : مشتركه\nالقريد النهائي F\n\nالصوت: واضح\n\nاضافات: الدكتور سيء جدًا مدري كيف يمدحونه مسوي الرجل النكيت وما يخلي احد بالحاله. تساله سؤال بكل جدية يرد عليك بكل سماجة. وشرح يعني سيء مرا يبي يخلص بس وما يحب الاسالة. اسوء دكتور ماث الصراحة!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536522-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/76", "user": "RS83", "ts": 1679917477000, "tid": 68415, "pn": 76}}]}', 1679917477000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-math002', 'stk-abo_yazeed6', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68468", "n": "Dr. Sayed Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور جيد وشرحه طيب ومتفاني وحريص على الطلاب\n\nمشكلته أنه ما يعجبه الطالب الي يعتمد على عقله وذكاءه في حل المسائل بدل أنه يمشي على القوانين بحذافيرها ,يعني مثلا كورس math 002 تحديدا في الدوال المثلثية ,الكل يعرف أنه ما في قوانين معينة تمشي عليها وممكن توصل للحل بطرق مختلفة ,سيد عمر ما يحب احد يختصر ويستخدم طرق الا طرقه هو ولو كانت طويلة.\n\nكويزاته من متوسطة الى صعبة,يعطيك حقك بالملي في الكلاس وورك لا يزيد ولا ينقص ,لكن ممكن يعيد لك كذا كويز بشروط معينة لكني نسيتها.\n\nأذكر أنه قال اللي يجيب بالميجر الثاني درجة أعلى من الكلاس تيست ,راح يرفع درجته في الكلاس تيست لنفس درجته بالميجر.\n\nختاما لا تحط راسك براسه ,لأنه رجال شايب ويزعل بسرعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1255606-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sayed-omar/68468/34", "user": "abo_yazeed6", "ts": 1377506104000, "tid": 68468, "pn": 34}}]}', 1377506104000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_sensi-math002', 'stk-mohammed_sensi', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68468", "n": "Dr. Sayed Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه math 002\n\nالتحضير :\n\nفي أول المحاضرة وبعض المرات ينسى مايحضر ( ترى عادي عنده تجي بسكشن ثاني بس بشرط ماتكون متأخر… يبي يدخل القاعة ويلقاك موجود أو بيقولك روح وتعال بالسكشن المسجل لك ) واذا مصختها بالتأخير راح يقولك “this is not an open cinema”\n\nطريقة الشرح :\n\nممتازة و بطلة صراحة يشرحل لك الكونسبت ولازم تفهم وانت عليك أنك تركز وبس “open your mind”\nأما عن النوت فهي مثالية perfect أمثلته كافية وملمة بالأفكار وفيها أمثلة من الكتاب ممتازة ومختارها بعناية وحاط لك بعد تمارين اضافية بعض أفكارها تكون من كتاب آخر او من عنده وفيها أيظاً أولد اكزام وطبعاَ مع “الحل الكامل” .\n\nوتراه يحل الرسايتشن ويحطها على ملف pdf في البلاكبورد بطريقة مرتبة وممتازة.\n\nبإخصار اذا فهمت النوت وقدرت تحل التمارين الإضافية راح تبدع تبدع بالمياجر والفاينل.\n\nالكويزات :\n\nمتوسطة وترا كلها من الكتاب و النوت ولا بعد COPE يعني السؤال نفسة الي في التمارين و التمارين الإضافية يجيبة لك بالرقم ويكتب بجانب كل سؤال هذا سؤال كذا\n\n* صراحة انا ماكنت افتح الكتاب مع انه كان يقول ترا بجيب من تمارين الكتاب بس اني كنت افهم النوت كامل والوضع 100%*\n\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:\nA+\nالصوت:\nبكل امنه لغتة ممتازة لكن يعيبها قليلاً الاكسنت * تتعود عليه* لاكن هذا شي غصبن عنه كونه افغانستاني.\nإضافات :\n\nاستاذ طيييييييب القلب واخلاق ويقدر الي يجية بالاوفيس ويرحب فيك حتى لو كنت مش طالبة واي شي مافهمته راح يعيد شرحة برحابة عكس بعض المدرسين واتمنا انه يدرسني في الجبل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438385-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sayed-omar/68468/36", "user": "Mohammed_sensi", "ts": 1452372853000, "tid": 68468, "pn": 36}}]}', 1452372853000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mashal_35-math002', 'stk-mashal_35', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68468", "n": "Dr. Sayed Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 172 ,Math002\nالتحضير : كيف أشرحه ؟ ، تجي متأخر دقيقة يمشيك ، إذا أكثر من كذا يخليك توقف ثواني بعدين يسمح لك تجلس ، إذا تأخرت ٤ أو ٥ دقايق (Late) ، أكثر من كذا يوقف الدرس يناقشك ليه متأخر .\n\nالشرح : مو ذاك الزود\nالكويزات : صعبة الصراحة و ذا الشي خلاني أكرف نفسي بماث ٠٠٢ و أسس نفسي صح ، ادرس عنده و بتفهم كيف آليته المعقدة بالكويزات و الكلاس تست .\nالتصحيح : يعطي بونص عالي الرجال لأن تأسيسنا قوي بماث ٠٠٢ (كله من نوتاته الأسطورية و كويزاته الصعبة) و ذا الشي خلانا نجيب فوق الأفرج بالمياجر … الزبدة دفني ٥ درجات (: .\n\nإضافات : الرجال يأسس الطالب بالمادة ، و نوتاته أسطورية LEGEND ، إذا معقدتك الأوريا ذاكر من نوتاته\n… سيد عمر ❤️ الله يذكره بالخير .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505081-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sayed-omar/68468/40", "user": "Mashal_35", "ts": 1547898529000, "tid": 68468, "pn": 40}}]}', 1547898529000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mujahed_alsaqabi-math002', 'stk-mujahed_alsaqabi', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68555", "n": "Dr. B Demir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 002 172\n\nالتحضير : يحطك حاضر الى 15 د ويسمح بالميك اب بشكل عام يعني اذا تغير كلاسك طول السمستر عادي\nطريقة الشرح : يشرح من سلايدات بوروينت … حلوة للشرح لكن جدا غير كافية للمذاكرة … يحل اولد اقزام كثيير والريساتيشن\nالكويزات : تقريبا عدد الكويزات يتراوح من 7-9 طبعا في النهاية مايقيم الكلاس ورك منهم\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B+\nالصوت: ممتاز يتكلم انجلش واضح ويقط عربي كثير لكن مايخرب المعلومة\nإضافات : ديمير ممتاز الصراحة اذا عرفت كيف تذاكر المادة معاه … انا كنت اركز معاه بالشرح وافهم الكونسبت واذا رجعت البيت احل اولد اقزام من نوتات الدكتور احمد مقبل … الميزة ان اغلب الاولد اقزام يكون حالها ديمير فأتاكد من فهمي اذا حليتها بنفسي …\n\nشغلة ثانية الدكتور مايحب الاسئلة الغبية ويزبد لك اذا سئلت عن شئ شرحه من قبل فخلك مركز طول الكلاس\n… ماقد رحت له اوفيس اور بس يقولون الشباب انه كويس ويشرح اذا منت فاهم شئ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493126-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-demir/68555/76", "user": "mujahed_alsaqabi", "ts": 1527463835000, "tid": 68555, "pn": 76}}]}', 1527463835000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muneer616-math002', 'stk-muneer616', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68648", "n": "Dr. Husam Sharqawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 002/182\n\nالتحضير : يحضر نهاية الكلاس ومرات ما يحضر ، متساهل جدا بالتاخير\nطريقة الشرح : عنده نوت يشرح منها وماتحتاج تكتب وراه لان كل شي موجود بالنوت واللكتشر الي ينزلها بالبلاكبورد، غالبا يطول بشرح الافكار\nالكويزات : متوسطة مائلة للصعوبة ، 4-5 كويزات وكلاس تيست واحد\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A ، برايي الدكتور تحتاج تشتغل من بعده بشكل بسيط ، يعني تحل اولد اكزام وبعض الاحيان تطلع على نوتات دكتور ثاني عشان تتمكن من الدرس او الفكرة\nالصوت:مسموع ولهجة واضحة\nإضافات : الدكتور قمة بالاخلاق وبالاحترام يبهرك باحترامه صراحة والابتشامة ما تفارقه، النوت حقه كويس لكن مش مرتب بشكل سهل استخراج المعلومة منه، مرات كثير اروح له المكتب باوقات ما عنده ساعات مكتبية ومايقول شي رغم زحمة الشغل الي عنده بحكم انه الكوردنيتر ، البونص حقه يعتمد على الاسئلة الي ينزلها قبل كل ميجر يعني الطالب الي يحل ياخذ بونص < لذا تشوف كثير طلاب يمكن ما يجيهم بونص لانهم ما يدرون او يتكاسلون بسبب كثرة الاسئلة، واخر شي هو انه محفز للطلاب بشكل كبير وبعض الاحيان يلوم الطلاب اذا ما راجعوا افكار الدرس السابق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510031-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husam-sharqawi/68648/66", "user": "Muneer616", "ts": 1558505530000, "tid": 68648, "pn": 66}}]}', 1558505530000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-math002', 'stk-user12137', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68648", "n": "Dr. Husam Sharqawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الشرقاوي هذا ما يحتاج حتى اكتب عنه, من افضل افضل افضل الدكاترة\nMath 002\nالتحضير : متساهل جدا بالتحضير والتأخير وما يهتم لهم الا اذا زودوها الشباب, ويحضر آخر الكلاس بمناداة السيريال نمبر\nطريقة الشرح : سلسلة ومبسطة وواضحة خلطة عجيبة والله, دائما يقول ما يحب التعقيد والكلام الطويل فتحس دائما شرحه كذا بسيط مهما كان الدرس صعب, البعض يقول ماث 002 صعب وكذا بس والله العظيم ما حسيت بأي صعوبة مع هالذيب\nالكويزات : صراحة كانت الاسئلة شوي فيها صعوبة, واعطانا كويزين مادري 3 اضافيات سهلة اسئلتها عشان نعدل درجاتنا\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A++++\nالصوت: جدا واضح وعالي وممتاز ويغير فيه عشان يجذب انتباهنا\nإضافات : الدكتور اخلااااااق ومتساعد ودائما يبغانا نسأل بل يزعل علينا اذا ما سألنا , والله انه خووش رجال\nاذا هذا الي يدرسك الحين اسجد سجدة شكر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534658-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husam-sharqawi/68648/69", "user": "user12137", "ts": 1655359851000, "tid": 68648, "pn": 69}}]}', 1655359851000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-math002', 'stk-abdullah2015', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68675", "n": "Dr. Khaled Saifullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده MATH002 ترم 152\n\nالتحضير :\nيحضر في أول دقيقة في المحاضرة، لا تتأخر نصيحة.\nطريقة الشرح :\nمن النوت حقته عن طريق البروجكتر، والمسائل يحلها على السبورة.\nالكويزات :\nكويزاته متوسطة الصعوبة إلى صعبة، إذا كنت قادر على حل الأسئلة معناها إن عندك فهم جيد للكونسبت مما سيسهل عليك المياجر :).\nتصحيحه في الكويزات خرافي جداً، ممكن تكون حال خطأ وفجأة تلاقيه عاطيك نصف الدرجة بس لأنه حس إنك فاهم 🙂 .\nالمياجر:\nكومون.\nالفاينلات :\nكومون.\nالقريد النهائي:\nيستحق A+ .\nالصوت:\nواضح لكن بعض الطلاب يواجهون صعوبة في فهمه بسبب الأكسنت.\nإضافات :\n* دكتور خالد سيف الله يعتبر من أفضل الدكاترة في السنة التحضيرية، والدكتور حسب كلامه إن له أكثر من 30 سنة في الجامعة، فهو معلم كبير في السن.\n* الدكتور عنده في النوت حقته Additional Homework لكل درس، إذا حليتها ورحت له الأوفيس أور راح يعطيك بونص، وهو بشكل عام يقدّر اللي يجيه الأوفيس.\n* أنصح بحل الAdditional Homework لأن فيها تركات شبيهة بتركات المياجر فيعني لو حليتها فأنت ضمنت البونص وراح تساعدك على الكويزات والمياجر إن شاء الله.\n* تقييمي له لكورس MATH002 أما كورس MATH001 ما أدري عن وضعه فيه.\n* يحب يمدح نفسه، يقول إنه The KING of the GRAPH … 🙂\n\nالله يوفقه ويطول في عمره، كان دكتور طيب الله يذكره بالخير 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457548-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-saifullah/68675/44", "user": "Abdullah2015", "ts": 1473781969000, "tid": 68675, "pn": 44}}]}', 1473781969000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-math002', 'stk-faisal_19', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f68675", "n": "Dr. Khaled Saifullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math002 - 162\n\nالتحضير : يومياً على الببورتال\nطريقة الشرح : عنده نوت خاص فيه جميل ومرتب وشامل، يشرح على السبورة وما يستخدم التقنية في غير التحضير.\nالكويزات : 5 كويزات وحذف أسوء واحد ، متوسطة للي مذاكر\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\n1- زي ما ذكروا الشباب فوق ، الدكتور خالد قمة في العلم ما شاء الله لكن يعيبه الاخلاق اثناء الشرح، بعض الاوقات ممكن يزل ويهزئ على سؤال مع انه في سياق الشرح لكن بالنسبه لشخص في مستواه يحس انه سخيف.\n2- كنت في اخر شعبه عنده فالدرس كان مكتوب على السبورة وهو من النوع اللي يكتب لأول شعبه والشعب اللي بعدها يشرح لهم نظري وهذا الشي صعب في مادة زي الرياضيات.\n\nفيما عدا هذي النقطتين الدكتور خالد عنده يعتبر من دكاترة القسم فوق الممتازين خصوصاً في 002 نظراً لمستواه الاعلى من 001 اللي يعتبر اساسيات بسيطة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474946-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-saifullah/68675/47", "user": "Faisal_19", "ts": 1497210576000, "tid": 68675, "pn": 47}}]}', 1497210576000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_assan-math002', 'stk-_assan', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f80396", "n": "Dr. I Naji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده Math 002 ترم 132 (آخر شهرين)\n\nالتحضير :\n9 من 10 (الإلتزام)\n*تقدر تحضر عند سكشن ثاني إذا فاتك الكلاس\n*الطلاب يحضرون قبله الكلاس\n*كان سكشنا الساعة 7 , وفيه ناس تجي قبل 7:15 ومايسجلهم غياب\n*كان يحضر نهاية الكلاس بالاكسل\n\nطريقة الشرح :\n10 من 10\nيستخدم كمبيوتره الخاص , عنده نوتتين (Two notes 😆) وحدة محلولة ووحدة بدون حلول\nنمر على الأمثلة والمفاهيم , يحل معانا (يعني يسألنا عن طريقة الحل, الناتج النهائي …إلخ)\nبعدين يعطينا أسئلة نحلهم بنفسنا , ويورينا الجواب\n\nالكويزات :\nالصعوبة 9 من 10\n*ياخذ أسئلة من الكتاب + أسئلة اولد اكزامز\n*فيه تركات\n*متشدد من ناحية الوقت (اذا قال 20 دقيقة معناتها 20 دقيقة)\n\nالمياجر:\nكامن\nالفاينلات :\nكامن\n\nالقريد النهائي:\nB+\n\nالصوت:\n10 من 10\nالاكسنت جدا واضح بالرغم من أنه مو نيتف سبيكر\n\nإضافات :\n\n*المدرس متمكن جداً من المادة\n*يوريك كيف ممكن الميجر يخدعك في الأسئلة\n*يعطيك ملاحظات مهمة جداً\n*كلاسه ممكن ماتكون فلة , لكنها عن 10 كلاسات عند المدرس اللي كنت عنده 🙂 (من ناحية الفايدة)\n*النوتات, الكوزات, الكلاس تستات, حلول الرسيتيشنات كلهم يرفعهم على البلاك بورد\n*المدرس مفيد , لكن علشان تتحقق الفائدة لازم تتابع معاه أول بأول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373455-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-naji/80396/42", "user": "_assan", "ts": 1401300024000, "tid": 80396, "pn": 42}}]}', 1401300024000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_bub-math002', 'stk-a_bub', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f80396", "n": "Dr. I Naji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH002 T162\n\nالتحضير : يحضر بنص الكلاس بس اذا جيت متأخر خلال 5 دقائق اعرف انه عرف وجهك وراح يحطك ليت اذا وصل لاسمك.\nيسمح بالميك اب احيانا ولكن مثلا كلاسك 8 وتبي تحضر 10 راح يحطك ليت بس مايغيبك بس اذا العكس يحضرك عادي بدون ليت 😐\n\nطريقة الشرح :نوتته الخاصة انصح انك تشتري نوتته الغير محلولة وتحل وتفهم وراه لانه في اشياء بالنوتة المحلولة مايكون منبه عليها بس هو ينبه وقت الكلاس.\n\nالكويزات :نفس كونسبت النوتة ومرات نسخ لصق من النوتة لو تذاكرها تاخذ فل مارك 👏\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي:B+\n\nالصوت:واضح\n\nإضافات :الدكتور من النوعية اللي لو تسأل سؤال بالاساسيات اللي انت نسيتها يا انه يسمعك ومايرد عليك او انه مايرد على سؤالك ولكن يطقطق عليك.\nتعامله جدا بارد والكل عنده سواسية بس شرحهه ونوتتة الى حد ما, تغطي على عيوبه + بالاخير الكل بونص 2 بالكلاس وورك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474755-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-naji/80396/52", "user": "A_BuB", "ts": 1496917381000, "tid": 80396, "pn": 52}}]}', 1496917381000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_a7md-math002', 'stk-king_a7md', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 -172\n\nالتحضير : دائما يحضر بداية الكلاس بالارقام، ما يدقق على التأخير البسيط ابو 3 دقايق\nطريقة الشرح : يشرح من السلايدات ويكتب على السبورة، وبعد ما نخلض الدرس يحل الريسايتيشن واولد اكزام، شرحه ممتاز جدا وواضح\nالكويزات : كويزاته كثيرة جدا، عطانا هذا الترم 9 كويزات اضافة الى 2 كلاس تيست، وتعتبر كلها صعبة، فلازم تكون متابع اول باول\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح ولكنة انجليزية جيدة\nإضافات : المدرس هذا اسطوري في الماث ومحظوظ الي ينزل عنده، اسلوبه فكاهي واخلاقه عالية ويهتم بالطالب، افرج سكاشنه عالي في المياجر وهذا يثبت تفوقه وما شفت طالب في دفعتي يشتكي منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493521-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/42", "user": "KiNG_A7MD", "ts": 1527928455000, "tid": 82373, "pn": 42}}]}', 1527928455000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammad-72-math002', 'stk-mohammad-72', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 002-term 182\nالتحضير: مايدقق عالليث بس التحضير يومي\nطريقة الشرح : يشرح من السلايدات حقت الكتاب ويحل ريسايتيشن ومياجر واجد ويهتم انه يحل مياجر وريسايتيشن\nالكويزات : شاملة للافكار اللي بالميجر وممتازة\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:+b\nالصوت: واضح ويشرح عربي وانجليزي\nإضافات : الدكتور كويس بس اسلوبه بالمزح كريه شوي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502996-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/43", "user": "mohammad-72", "ts": 1543375866000, "tid": 82373, "pn": 43}}]}', 1543375866000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math002', 'stk-user11372', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 -182\n\nالتحضير : يحضر بالسيريال نمبر حقك , ممكن تتأخر معه 5 دقايق او 7 دقايق ويحطك حاضر بس لاتفلها كل يوم , الميك اب يسمح فيه مثلا يوم او يومين بالسمستر بس اذا غبت او نمت عن كلاسك مثلا عادي يرضى لك بس طول السمستر لا\n\nطريقة الشرح : يشرح من سلايدات عنده وهي سلايدات الكتاب وشرحه جداااااااااا اسطوري وكافي واذا خلص الشرح يفتح الاولد اقزام ويبدا يحل الين ماتنتهي الحصة الدكتور شرحه رهيب ماذكر مره طلعت وانا مو فاهم , شرح ولا اروع والله وكافي ويغطي جميع افكار الدرس وقبل الميجر بكم يوم (غالبا باسبوع) يبدا يحل الريستايشن والاولد اقزام كلها واله عندي أي سؤال روح الاوفيس والدكتور حبوب جدا ويقدر الطالب اللي يجيه بمكتبه ومعه اسئلة يعرف انك متابع للمادة\n\nالكويزات : كويزاته اسبوعيا لكن غالبا تكون في عدد دروس قليلة مثلا درسين او درس , نهاية السمستر اختبرنا احنا 9 كويزات و 2 كلاس تست , نصيحة جدا مهمة : اله تبي بونص حاول لاتغيب , لان الغياب راح يأثر عليك بالبونص حاول لاتغيب اكثر من 1 او 2 اذا مره قفلت , افكار الكويزات تجي نفس الاولد الاقزام والريستايشن , حتى مره جاننا تقريبا 5 اسئلة بالميجر نسخ لصق من كويزاته\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+ مع مرتبة الشرف الاولى !\n\nالصوت: واضح جدا الدكتور اصله مغربي وحاليا معه الجنسية الامريكية , الصوت واضح جدا يشرح كوكتيل عربي - انجليزي\n\nإضافات : لو نزل لك هذا الدكتور احمد ربك ليل ونهار لانك من اصحاب الحظ القوي فعلا !!! صدقني اتعب والدكتور اله شافك تبذل جهد مابيقصر معك والله والدكتور اسطوره وانا اقول افضل دكتور درسني ماث بحياتي , والله ثم والله حببني بالمادة , حاول تشد معه بالكويزات وكلاس تست وصدقني بتطلع بالكورس A+ , احيانا ارجع البيت مايحتاج اراجع لاني فاهم 100% من كلاسه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508753-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/44", "user": "user11372", "ts": 1555603940000, "tid": 82373, "pn": 44}}]}', 1555603940000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-math002', 'stk-kirsty13', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH002-182\n\nالتحضير : كل يوم عن طريق السيريال نمبر ولاتحضر خويك لانه يعد الطلاب وما عنده مشكلة مع التاخير\nطريقة الشرح : يشرح عناصر الدرس وسلايداته بسيطة وحلوة للكونسبت وثم على طول يدرعم اولد اكزامز ويشرح خطوة خطوة ما يلخبطك ابدا ويتقبل الاسئلة بصدر رحب\nالكويزات : متوسطة مائلة للصعوبة , اذا حليت كويزاته وجبت درجات عالية وانت فاهم ما عليك خوف ابدا لانها مقاربة لمستوى المياجر او اسهل بشوي وافكارها متنوعة\nالمياجر: من الديبارتمنت\nالفاينلات : من الديبارتمنت\nالقريد النهائي: طلعت معه B , لكن الصراحة اعطيه +A\nالصوت: واضح وجهوري ما شاء الله ولاهو اللي بمزعج وبتسمعه لو انك في اخر القاعة\nإضافات : هذا الدكتور اذا جاك فانت جدا محظوظ , عنده مشكلتين وحده منهم انه يتحمس ودايم يقول (عملناه) راح تسمع هذي الكلمة كثيير :speech_balloon: واذا كان كلاسك دوافير مثل كلاسي ف راح يصير الوضع تشقيح مسائل ولكن اذا كلمته انه يحلها م بيقول شي حتى لو عشانك انت لانه يقول م اقدر اعدي وطالب واحد مش فاهم و الثانية البونص حقه يعتمد على مياجرك وحضورك وعدم امساكك للجوال وللاسف انه قليل مو كثير يعني شد حيلك ف الكويزات . خلوق جدا الصراحة وقريب من طلابه مره والميك اب عنده مسموح :popcorn:بس لاتفلها واحيانا لازم تعطيه خبر قبلها.\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510460-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/45", "user": "Kirsty13", "ts": 1559352072000, "tid": 82373, "pn": 45}}]}', 1559352072000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math002', 'stk-guest', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: math002\nالترم: 192\n\nالتحضير: من خمس الي عشر دقايق ويحضر ب الارقام (تقدر تخلي خويك يحضرك كم مره بدون مايلاحظ)\nالميك اب عنده حسب المزاج\n\nالشرح: الصراحة الدكتور مره سيء ومحد فاهم وش قاعد يشرح، شرحه مو منظم عادي يبدا الدرس ب مسائل اولد اكزامز ودايم يدور الاسئله السهله علشانها ماتاخذ وقت، مايغطي كل شيء ف الدرس عن نفسي كنت احضر عند الياس الشاويش (درسني ١٩١) وهذا الشيء فادني كثير، نصيحة للي يجيه لاتعتمد عليه حاول تذاكر بنفسك او احضر عند دكتور ثاني وعنده تك ورى وخلك على الجوال لانك ماراح تستفيد منه كثير\n\nالكويزات: درجاتي كانت عاليه فيها لاكن الافرج كان طايح فيها، بعض المرات يشرح لك الكويز وقت الكويز وكيف فكرة بعض المسائل وبعض المرات يغشش بعض الطلاب وبعضهم يسحب عليهم\n\nالتعامل: الدكتور قلبه طيب للامانه\n\nالقريد النهائي: D+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522275-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/13", "user": "Guest", "ts": 1590206237000, "tid": 172443, "pn": 13}}, {"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(MATH 002 - 192 (COVID-19\n\nالتحضير : يحضر يوميا بداية الكلاس بالسريال نمبر، ما يدقق واجد على التأخير\nطريقة الشرح : شرحه ممتاز جدا يبسط الامور ما يعقدها، في البدايه يشرح الكونسبت ويحط مسائل خفيفه في السلايد على الكونسبت، بعدين يفتح الاولد أقزام ويحل على الدرس مسائل (هذا الي يميزه)\nالكويزات : متوسطه مائله الى الصعوبه، تدرب اولد اقزام ولا تشيل هم\nالمياجر: كومون\nلفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح جدا\nإضافات : الدكتور في سلبيه كنت اوجهها معاه الي هي كل ما اروح الاوفس اور نادر الاقيه موجود. بس لو حصلته ما يقصر\n\nكلمتين بتسمعهم طول الترم، (عملناه) و (Oh brother)\n\nالحصه معاه ممتعه ويحب يمزح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524623-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/46", "user": "Guest", "ts": 1597213810000, "tid": 82373, "pn": 46}}, {"id": "stk-dr-m172444", "n": "Dr. Audu Johnson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 002 - 192 (نصف الفصل أونلاين)\n\nالتحضير : شديد شويتين بالتحضير حاول تجي بدري دايم\n\nطريقة الشرح : ممتاز جدا جداااااااااااااااااااااااااا اتعب وانا اقول ممتاز من الاساتذة النادرين اللي مستحيل تطفش من كلاسه وهو يشرح, يشرح من النوتته اول شيء وبعدين يعطي مسائل كونسيبت وبعدها يعطي سؤال مستواه عالي شوي\nطبعا بعد ما صار الترم اونلاين اشوفه ما تغير كثير عن الحضوري لكن شرحه صار ابطأ\n\nالكويزات : نص ونص مائل للصعوبة لكن حاول تستفيد من الاسئلة لأنه جدا افادتني شخصيا ويعطي عليها بونص نهاية السمستر\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: اعطيه A+\n\nالصوت: واضح ولهجته واضحة رغم انه افريقي\n\nإضافات : الدكتور متساعد وحبوب جدا بس يكره يشوف احد مشغول بشي نص الكلاس, ويكره الطالب المهمل بعد.\nو اضافة مهمة نسيت اذكرها انه بعد كل درس يعطي واجب 20 سؤال ويبغاك تحلها بالخطوات كاااااملة. طبعا أنا شخصيا فادتني واجد وبعد فضل الله قدرت اجيب فل مارك بالميجر الأول وحتى يوم درسنا أونلاين جبت الفل بالراحة بالفاينل -رغم انه مستواي ماش بالماث 🚬-\nلكن اللي جدوله ثقيل او غثيث بينزعج منها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526644-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/audu-johnson/172444/9", "user": "Guest", "ts": 1605126970000, "tid": 172444, "pn": 9}}]}', 1590206237000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhm14-math002', 'stk-mhm14', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f98615", "n": "Dr. Hamoud A Dehwah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 - Term 132\n\nالتحضير: يوميا نهاية الكلاس، متساهل نوعا ما مع التأخير\n\nطريقة الشرح: يبدأ باستعراض أهداف الدرس ثم يحل مثال حتى توضح الفكرة و بعدها يكتب النوت على السبورة و نكتب وراه، كانت الطريقة هذي مملة و النوت كان نفس اللي بالكتاب بالنص فما شعرت بقائدة كبيرة، كان همه الأكبر إنه الطالب يفهم الدرس و كان يحاول إنه ما يطلع أي طالب من الكلاس إلا و هو فاهم الدرس، مخلص في عمله\n\nالكويزات: سهلة جدا جدا، نفس الكتاب و الريسيتيشن، كان كل يوم ثلاثاء كويز و اختبرنا 10 كويزات تقريبا، الكلاس تست اختبرنا مرتين و نفس الأفكار بالكتاب و الريسيتيشن، تصحيحه متعاون و مو شديد\n\nالمياجر و الفاينلات: لا شيء يُذكر\n\nالقريد النهائي: أعطيه B\n\nالصوت واضح جدا\n\nإضافات: الدكتور أخلاقه رائعة و لكن أكثر شيء يكرهه إنه الطالب يحضر بسكشن ثاني\n-كان أفرجنا في المياجر عالية مقارنة ببقية الطلاب في الكورس\n- الدكتور ساعدني كثير بالكلاس ورك، زودني 3 درجات عن اللي استحقه، كان قال لينا إنه ما بيزود درجات لأن أفرج سكشنا بالمياجر عالية، لكن زودني و ما قصر جزاه الله خير\n-كان يخلص ماتيريل المياجر قبل إسبوع من الميجر و كان يعمل لنا مراجعة و يحل بعض أسئلة أولد اكزام\n- أنا كنت مقصر كثير بالمادة لكن الحمدلله نجحت فيها و الدكتور ما قصر معانا\n- الكورس مع الدكتور جيد لكن لازم تعتمد على نفسك بالمقام الأول و تحل أسئلة كثيرة و ما تخلي الأمور تتراكم عليك و تكون متابع أول بأول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373650-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-dehwah-hamoud-a/98615/8", "user": "MHM14", "ts": 1401332381000, "tid": 98615, "pn": 8}}]}', 1401332381000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-math002', 'stk-sultan_salman_1419', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 … Term 163\n\nالتحضير : قبل نهاية الكلاس\n\nطريقة الشرح : للأمانة شرحه مميز جدا … لكن لازم تكون منتبه لأنه في بعض الأحيان يصير ممل شوي … النوتة ممتازة وبرأيي الشخصي : النوتة + أولد اقزام = قريد عالي بالمادة بإذن الله\n\nالكويزات : ٥ كويزات و٢ كلاس تيست … اتوقع في الاترام العادية ممكن يعطي كويز أو كويزين زيادة وهذا لمصلحة الطالب عشان الكلاس وورك\n\nالمياجر : كومون وركز على النوتة والاولد اقزام\n\nالفاينلات : كومون وركز على النوتة والاولد اقزام\n\nالقريد النهائي : +A ومستحقة\n\nالصوت : شخصيا أنصحك بالجلوس في المقدمة عشان يكون الصوت واضح\n\nإضافات : الدكتور هذا لو جاك احمد ربك … من افضل الدكاترة … محترم جدا وخلوق ومتعاون بالاوفيس الاور … ما راح يقصر معك بالكلاس وورك … الله يسعده وين ما راح يارب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479838-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/18", "user": "sultan_salman_1419", "ts": 1504775172000, "tid": 118561, "pn": 18}}, {"id": "stk-dr-f98615", "n": "Dr. Hamoud A Dehwah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 … Term 162\n\nالتحضير : يختلف الوقت من حصة لحصة ولكن في الغالب بداية الحصة\n\nطريقة الشرح : لا بأس بها … شرحه للمسائل السهلة والمتوسطة … ما يشرح المسائل الصعبة ( اللي تجي منها المياجر ) … تأخذ نظرة على أغلب أسئلة الاولد اقزام … تقول في نفسك \" هذا أخذناه !! \"\n\nالكويزات : سهلة إلى متوسطة وتحتاج للمذاكرة … أما الكلاس تيست من متوسط لصعب … ويحتاج لمذاكرة فعلية\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: B\n\nالصوت: لا بأس به ولكن يفضل الجلوس في المقدمة\n\nإضافات : مدرس متعاون بالاوفيس اور … ما يحب يشوف احد يمسك الجوال … بونصه جيد حول ال3 درجات … يبي من الطلاب يكتبون النوت اللي يكتبه في السبورة … تحتاج لجهد عالي في المادة لأن شرح الاستاذ ما يكفي بالذات في المياجر والفاينل .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1481567-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-dehwah-hamoud-a/98615/11", "user": "sultan_salman_1419", "ts": 1507557762000, "tid": 98615, "pn": 11}}]}', 1504775172000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng_alsubaie-math002', 'stk-eng_alsubaie', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f98615", "n": "Dr. Hamoud A Dehwah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 002 - TERM 182\n\nبنود التقييم :\n\nالتحضير :\nعلى بداية الكلاس بالضبط اذا دخلت متأخر وهو يحضر يمكن يمشيك\n\nطريقة الشرح :\nيشرح فكرة الكونسبت بعدها يبدا يحل الاسئلة من نوتاته\n\nالكويزات :\nمتوسطة تميل للسهوله اذكر عطانا سبع كويزات وخذ احسن خمسة الكلاس تيست اثنين قبل المياجر ومستواها مثل الكويزات\n\nالمياجر: من الديبارتمنت\n\nالفاينلات : من الديبارتمنت\n\nالقريد النهائي: A+\n\nالصوت: ,واضح\n\nإضافات :\nالدكتور يشهد الله على اخلاقه العالية وتعامله مع الطلاب يعتبر طلابه كلهم مثل اولاده الله يوفقه ويخلي له عياله\nالكويزات والكلاس تست غير موعدها اكثر من مرة على رغبت الطلاب\nالطالب المهتم ياخذ حقه وزيادة\nما يحب يشوف احد يمسك الجوال\nما يحب الطالب يتأخر\nاذا ما فهمت شيء رح للدكتور المكتب وبإذن الله ماتطلع الا وانت فاهم\nوأهم شيء لاتاخذ فكرة سيئة عن الدكتور من الطلاب لانهم ظالمينه الصراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510182-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-dehwah-hamoud-a/98615/12", "user": "Eng_Alsubaie", "ts": 1558815012000, "tid": 98615, "pn": 12}}]}', 1558815012000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-math002', 'stk-someone33', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\n\nMath002 Term212\n\nالتحضير : بداية الكلاس مافيه تأخير حتى لو دقيقة\nطريقة الشرح : سلايداته ، حلوة و تنفع للكويزات و الكلاس تست و الميجرز و الفاينل\nالكويزات : مقالية من ١٥ و فيه بونس او بونسين كل كويز و كلاس تست\nالصوت: ممتاز\nإضافات : ممنوع الجوال منعا باتا حتى لو على الطاولة ، ممنوع التابلت او الايباد\nالتقييم النهائي : 9/10\n\n--------------------------------------------------------------\nالتحضير : شدييييد جداً بالدقيقه الاولى يبدا يحطك ليت\nطريقة الشرح :بسلايداته شرح بعدين يبدا يحل اسئلته— اولداته فوق مستوى المياجر و حلهم مره وحده بس لا تطول لانها مضيعه وقت\nالكويزات :متوسطه الى صعبه افرجها دايم ٧-٩من ١٥\nالصوت:واضح\nإضافات :بالدقيقه يبدا الكلاس و يطلع منه— يحطك براسه لو طلع منك شي\nالتقييم النهائي :\nيعتبر جيد جداً الى حد ما بس ذاكر و تتسهل ان شاء الله\n\n--------------------------------------------------------------\nالتحضير : من اول ثانية بالكلاس\nطريقة الشرح : ممتازه عنده سلايدات يستخدمها تغطي جميع الافكار واذا ركزت معه ترتاح بالمذاكره الذاتيه\nالكويزات : كلها تجي من افكار سلايداته لكنها صعبه للامانة فيها تحدي ، السلايدات اخرها 8-9 اسئلة براكتس افكارها نفس الافكار تجي بالكويزات اذا حليتها كلها تمام بفهم اضمن درجه حلوه بالكويز ، كويزاته صعبه صراحه لكن تسهل عليك بعدين بالمياجر وفيه بونص دايم بكل كويز\nالصوت: ممتاز وواضح\nإضافات : الكويزات والكلاس تيست مستواهم صعب وقد يكون اصعب من الميجر هذي ميزه انها تسهل عليك الميجر لكن بتنخسف بالكلاس وورك اذا ماشديت بالكويزات ، سلايداته ممتازه ولها شرح باليوتيوب بقناته ممتازه صراحه وتسهل الفهم ولكن افكاره جدًا صعبه\nالتقييم النهائي : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535019-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/14", "user": "SomeOne33", "ts": 1660598343000, "tid": 176966, "pn": 14}}, {"id": "stk-dr-f98615", "n": "Dr. Hamoud A Dehwah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math002 - Term212\nلتحضير : متساهل في بداية الترم كان مايعطيك ليت ولا غياب لانه يحضر نهاية الكلاس ومن بعده بدا يحس الطلاب يفلونها والصدق كنا نفلها فا صار شديد يحضر من اول دقيقة ويعطي ليت لين اخر الترم رجع حبيب بالتحضير \"طبعاً الرجال ماعنده غياب ابداً كله ليت \" الا اذا طبعاً ماحضرت الكلاس نهائياً .\nطريقة الشرح : الله المستعان … سيء وماحد يفهم الا قلة ونص الى ثلاث ارباع الكلاس بأجهزتهم اتكلم بصراحة المادة معه كانت سلف ستدي يشرح بملفات pdf سيئة المادة مره سلف ستدي معه هو يحاول بس ماينفهم .\nالكويزات : للأمانه اول كويزين بسيطين وسهلين بس من ناحية كويزات اسهل من غيره …اقدر اقيمه من سهل الى متوسط .ومتوسطه غالباً .\nالصوت: ضعيف ويجيب النوم بصراحة.\nإضافات : الدكتور كان يصحح لي احياناً ومايعطيني حقي “الي اشوفه انا” واذا ناقشته يقولي هذا حقك ومرات يدف بس بالاخير ضبطنا بالكلاس وورك عطانا بونس درجة ونص كذا الدكتور حبيب الصراحة بس مايفيد لذلك ما انصح فيه .\nالتقييم النهائي : D .لو صار عندك حاول تسوي مثل بعض اخوياي “راحو للكوردنيتر او حق التسجيل” عشان يغيرون دكتورهم لانو فيه خيارات كثيرة من دكاترة افضل .هذا رأيي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535021-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-dehwah-hamoud-a/98615/14", "user": "SomeOne33", "ts": 1660604723000, "tid": 98615, "pn": 14}}, {"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nMath002 - Term212\n\nالتحضير :متساهل كثير ويعطي ليت اذا تاخرت نص ساعه وكذا\nطريقة الشرح : يشرح على الشاشه وشرح واضح وكذلك يشرح دروس على السبورة \" ون نوت \"\nالكويزات : اسوء مافيه الكويزات صعبه حقيقه لكن غير ماهي مستحيله بس صعبهه\nالصوت:صوته منخفض ويغلب الجو على الكلاس هدووء بس تقدر تسمعه حتى لو جالس اخر مقعد وواضح\nإضافات : لا تتساهل بكويزاته لانك بتلقم اذا ما ذاكرتها زين + ما يستقبل اوفس الا لطلابه الي يدرسهم\nالتقييم النهائي : دكتور بطل لو ما يمسك الدرجات عن نفسي ما افكر انزل عنده بسبب الدرجات لكن لو ابي بس افهم ولا خايف على الدرجه بنزل عنده.\n\n--------------------------------------------------------------\nالتحضير :تحضيره اسطوري تجي باي وقت يعطيك حاضر وحتى لو ما لحقت التحضير كلمه نهاية الكلاس وبيحضرك المفروض\nطريقة الشرح : شرحه اسطوري بكل ما تعنيه الكلمة من معنى اول شي يستخدم ال ون نوت وقبل بداية الدرس يعطيكم الافكار الرئيسية ويفهمكم اياها بعدين يبدا يمر عالافكار مرة ثانية ويعطيكم افكار الاولدات بحيث لو مريتو تكونو فاهمين كلشي ويعطيكم اشياء تجي بالمياجر والفاينل يعني حرفيا لو تركز معاه بكل تفاصيل الكلاس بتضمن درجات اسطورية\nالكويزات : اصعب كويزات اشوفها لكن هذا كله لمصلحة الطلاب لان بالاخر لو افرج الكويزات اقل من افرج المياجر بيزودكم درجات وكمثال ذا الفصل زود كل واحد فينا ٤ درجات ونص بحكم ان افرج مياجرنا عالية وافرج كويزاتنا قليلة ف بشكل عام اي دكتور كويزاته صعبة هذا لمصلحتك مهو ضدك\nالصوت:الدكتور هادي مررة وبارد شوي لكنه مدرسة بالاخلاق عالعموم لو سالته يرفع صوته بيرفعه وحاول تجلس اول شي وتركز معاه صدقني مستحيل تندم مستحييييييييييل\nإضافات : هذا من وجهة نظري افضل دكتور ماث بالسنة التحضيرية وبلا منازع ومستحيل احد يتفوق عليه حرفيا اكثر سكشن جايبين قريدات حلوة درسو عنده ولو جاك هذا الدكتور انت كل المملكة راضية عنك صدقني\nالتقييم النهائي : A+++++++++++++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535022-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/21", "user": "SomeOne33", "ts": 1660605132000, "tid": 118561, "pn": 21}}, {"id": "stk-dr-f176962", "n": "Dr. Ahmed Abdelrazec", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nMath002 - Term212\n\nالتحضير :يحضر بالدقيقة اول الكلاس وشديد بالتحضير\nطريقة الشرح :جدًا ممتاز يشرح الكونسبت اول ٢٠ دقيقة بعدها يدخل اولد والكلاس الي بعد الدرس يحل اولد على الدرس ويحل على كل الافكار مايعدي كل درس الا وهو متاكد انه الكل فاهم\nالكويزات :10 كويزات\n٧ كوزات الي بتتحاسب عليها و٣كوزات اضافية والدكتور عسل يعطي بونص واختبارات منزلية اضافية احيانًا على حسب الافرج\nالصوت: واضح\nإضافات :يفضل تروح الكلاس وانت فاهم الكونسبت\nالتقييم النهائي :9/10\n\n--------------------------------------------------------------\nالتحضير :يحضر مع أول ما يبدأ الكلاس مباشرة بالأرقام،و الي متأخر(وصل أو ١٠ دقايق) يسجله متأخر نهاية الكلاس و يدقق على الوقت\nطريقة الشرح :يركز على الكونسبت بحيث أنه يشرح المطلوب و ما يطول و يبدأ على طول في حل الأسئله،ما ياخذ وقته في شرح الكونسبت …\nحتى في حل الاسئله يختصر خطوات واجد فـ أحيان واجد تكون غير مفهومه و نضطر نسأله يعيد الحل أو يشرح خطوه خطوه…\nو عادي جدًا يحل أو يشرح سؤال كامل بالكلام بس،بدون ما يمسك أي قلم!! …\nالدكتور يعطي الطلاب طرق بحيث انهم يحفظون و هالشيء ما كان عاجبني أبدًا…\nالشرح و الكلام عادي بالعربي\nالكويزات :بمستوى الاولدات و مستوى الرسيتيشن + يحط سؤال كذا فيه فكره و يكون شارحها من قبل أو موصي عليها…\nاختبرنا ١٠ و أخذ افضل ٧ كويزات…\nتقريبا كل اسبوع كويز\nالصوت:الصوت واضح و يشرح بالعربي و يعطيها انقليزي على خفيف\nإضافات :الدكتور كان عاجب طلاب واجد بس ما عجبني في الشرح…أخلاق و محترم و يحب ياخذ و يعطي مع الطلاب،جتى بالاوفيس اور…\nالجوال لا تمسكه بالكلاس و لا بتطلع برا\nالتقييم النهائي :ممتاز جبت A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535024-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-abdelrazec/176962/5", "user": "SomeOne33", "ts": 1660605498000, "tid": 176962, "pn": 5}}]}', 1660598343000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abood_alem-math002', 'stk-abood_alem', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 - 152\n\nالتحضير :\nيحضر في آخر الكلاس.\nالدكتور متساهل جدًا في التأخير والميك اب, وعلى بلاطه ما عنده شي اسمه ليت 😆. لدرجة اني اذكر يوم تاخرت على الكلاس بسبب ظرف ودخلت وكان باقي على الكلاس 5 دقائق وحضرني ❤️\n\nطريقة الشرح :\nرائعة جدًا جدًا جدًا. شرح وافي وكافي ويفهمك كل شي وطريقة شرحه ممتازة.\nيبدأ الشرح عن طريق كتابة القوانين على السبورة. ثم يعطي مثال سهل ثم اصعب ثم اولد اقزام. يفهمك الكونسبت مضبوط بالطريقة ذي.\nنوتته مكتوبة بخط اليد لكن واضحة ومرتبة وفيها اولد اقزامز كثيرة.\n\nالصوت:\nواضح جدًا ولغته الإنجليزية مفهومة وواضحة, بعض الناس يمكن ما يعجبهم طريقة كلامه الباردة لكن بالنسبة لي ممتازة\n\nالكويزات :\nكويزاته سهلة مائلة للصعوبة, لو انت مذاكر اول بأول معه تجيب فل مارك بالراحة.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\n+A ولو فيه درجة اعلى اعطيته بعد 😆\n\nإضافات :\nالدكتور حبيب بمعنى الكلمة ويعاملك على انك اخوه. يجاوب على اي سؤال مهما كان بسيط او تافه بصدر رحب. ودي لو يحطونه بالجبل ثاني مره علشان انزل معه 🤠. اذا نزلك الدكتور هذا بالأوريا لا تقصر معه وابشر بالـ +A. دفنا في نهاية الكورس كم درجة بونص 🌹.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1453031-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/13", "user": "Abood_Alem", "ts": 1467385035000, "tid": 118561, "pn": 13}}]}', 1467385035000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ekko-math002', 'stk-ekko', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 - 162\n\nالدكتور محترم بشكل كبير جدًا مثل ماقال الكل؛ متساعد مع الطلاب بشكل كبير؛ التحضير يومي ونهاية الكلاس. “ماعنده شيء اسمه late”\n\nحتى ان بعض الطلاب يدخل اخر عشر دقايق ومايكلمهم؛ بس مع ذلك البعض يزودها كثير (الله يهديهم).\n\nكان كلاسي الساعه ٧ فكان متفهم كثير؛ طبعًا شرحه ممتاز وكويزاته اغلبها من المذكره والاولد اقزام اللي يحطه ع البلاك بورد؛ يعني لو بس تذاكر اللي يرسله لك تضمن الفل مارك.\n\nالبعض يقول انه كلاساته تجيب النوم برأيي بالعكس كلاساته ماتحس فيها وسريعه ودائما يطلعك قبل نهاية الكلاس بخمس دقايق.\n\nولو راح الجبل ماراح اتردد اني انزل عنده ^^", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474425-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/16", "user": "Ekko", "ts": 1496458192000, "tid": 118561, "pn": 16}}]}', 1496458192000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohannadhs-math002', 'stk-mohannadhs', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 002\nterm 161\n\nالتحضير :\nبالارقام لو حضرت خويك م بيركز\nواذا تاخرت م عندك مشكلة\nويقبل ميك اب\nطريقة الشرح :\nشرحة جيد ويقول اللي مو فاهم يوقفني ويسالني لا يسال زميله\nالكويزات :\nمرات سهلة ومرات صعبه\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nb\nالصوت:\nضعيف نوعا ما واذا حس ماحد فاهم بالانجليزي يبدا يشرح عربي\nإضافات :\nاخلاق جدا هالدكتور بصراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1489848-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/19", "user": "mohannadhs", "ts": 1522174849000, "tid": 118561, "pn": 19}}]}', 1522174849000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-h2121-math002', 'stk-h2121', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم212\nMath 002\nالتحضير : مرن جدا في التحضير يحضر غالبا بعد نصف الوقت وبعض الاوقات يراعي الطلاب ويسمع بال ميك اب\nطريقة الشرح : يشرح من الون نوت عنده نوتة خاصه فيه وانا اشوفها تكفي للمياجر واما عن شرحه فهو لايعلى عليه\nالكويزات : متوسطة الى صعبة بس مقدور عليها اذا ذاكرت نوتته كاملة\nالقريد النهائي: A+ ولو فيه اعلى يستحق\nالصوت: صوته واضح لكن بارد بس مايجيب النوم\nإضافات : الدكتور قمة في الاخلاق ومتعاون مع الطلاب بشكل كبير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535456-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/22", "user": "H2121", "ts": 1664674948000, "tid": 118561, "pn": 22}}]}', 1664674948000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-math002', 'stk-user8581', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f152153", "n": "Dr. Syed Khawar Kirmani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": ":\n\nكيرماني كأخلاق و فهم للكورس ممتاز لكن كشرح ماهو بذاك الزود , احيانا يطلع لك طرق جميلة غير الموجودة في الكتاب ويختصر لك بعض الاشياء … انا صرت عنده في Math002 وخفت من الكلام الي سمعته من طلابه في math001 لكن حاولت اني اذاكر يوميا واذا صار عندي وقت فاضي احضر عند دكتور ممتاز مثل ابراهيم ناجي عشان افهم الدرس واذا جا كلاس كيرماني اشارك معاه او اقعد احل الريساتيشن لأن شرحه ملخبط ومب مرتب ويقعد يشخبط على السبورة على قل معنى .\nطريقته هي :\n# يفتح الكتاب وعلى طول ع الاسئلة الي نهايةالدرس ويقعد يحل فيها او يخلي الطلاب يحلونها ويشرح الدرس من خلال حل الاسئلة … ( وهذي طريقة هي خلت اغلب طلاب يرسبون عنده شلون تبي الطلاب يحلون السؤال وهم ماعندهم فكرة عن الدرس وعن القواعد الي فيه )\n\n#كويزاته والكلاس تيست نسخ لصق من الاولداقزامات + الريسايتيشن …حاول تحل الريساتيشن في نفس اليوم او الاسبوع الي تاخذهم فيه …لأنك راح تفهم الدرس عدل وتطلع ع افكار اكثر وفي نفس لوقت تذاكر للكويز …قبل اي كويز حاول انك تاخذ اولد اقزام مقسم بحسب الشابتر وتحل الشابتر الي في الكويز … ( كويزاته 5 اقل شي واحيانا يخليهم 8 ويحذف منهم الاسوء وفيه 3 كلاس تيست )\n\n#الكلاس ورك عنده يعتمد على درجتك في المياجر …لو انك جايب العيد ودايما تتأخر عن الكلاس لكن انك في المياجر جايب 18 وفوق راح يعطيك اقل شي 22 من 24 في الكلاس وورك وهذا ظلم, يحضر اخر 5 دقايق ولو تجي قبل دقيقة من نهاية الكلاس يحضرك .!! اهو يكره هالحركة لكن مايسوي شي وللأسف احيانا الي يسون هالحركة يعطيهم كامل في الكلاس وروك…\n\nالزبدة : ذاكر الكتاب( قبل الكلاس) > حل الاسئلة الفردية >حل الريسايتشين بشكل مستمر ولاتقول بحل الاسبوع الجاي او في الويكند >ذاكر الاولداقزامات قبل الكويزات والكلاس تست\n\nنصحية لاتسحب وتغيب عن كلاساته حتى وان كان شرحه دمار لكن حضورك يخليك عارف الوضع وعارف وين وصلتوا في المنهج انا اقولكهالشي لأن اغلب الي رسبوا في السكشن الي معاي كانوا ساحبين عليه ومايحضرون الا اخر 5 دقايق + حاول انك تجمع درجات ولا تتوقع انه راح يزيدك في نهاية السمستر …لا ماراح يزيدك الا قليل درجة يمكن بالكثير درجتين ومب كل الطلاب راح يحصلون زيادة .\nانا سويت هالأشياء والحمدلله خذت a عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1293460-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-khawar-kirmani/152153/3", "user": "user8581", "ts": 1385322249000, "tid": 152153, "pn": 3}}]}', 1385322249000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alwaleed1-math002', 'stk-abo_alwaleed1', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 -162\nمن ناحية التحضير : يحضر كل يوم وبعض الأحيان ما يحضر إذا كان مطر وكذا …\n\nالكويزات متوسطة إلى سهلة ، لأنها من الريسيتاشن ويكون قد شرحها من قبل …\n\nطريقة الشرح ملخبطة ، ماهو مرتب ، بس ميزته إنه يشرح الريسيتاشن وينزلها على البلاك بورد ، وينزل أولد اكزامز بعد … لكن طريقة شرحه ماهي مرتبة والأفضل تدرس بنفسك …\n\nالصوت واللهجة : واضحة ويشرح بالعربي والانقليزي …\n\nأخذت عنده A وباقي لي درجة على A+ لكن مو منه ، من دراستي بنفسي …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474393-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/7", "user": "abo_alwaleed1", "ts": 1496420887000, "tid": 172443, "pn": 7}}]}', 1496420887000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nvm-math002', 'stk-nvm', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 - 162\nالتحضير : يومي واحيان ينسى ومايحضر، يسمح تحضر بسكشن ثاني ومايحساب عالتأخير الى ٧ دقائق.\nطريقة الشرح : عاديه لكنها مب الأفضل، ببداية السمستر قال الشرح بيكون عالكتاب وكل شي منه وتأزمت لكن من ثاني اسبوع حوّل على سلايدات ماي لاب بلس وكانت أفضل بكثير.\nالكويزات : متوسطة مائلة للسهولة، لو تفهم افكار اولد اقزام بتحلها.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: يشرح بالعربي بأكثر الاوقات واشوف انه لو يشرح بالانقليزي يكون افضل لان عربيته شوي مضروبه وماكنت افهم عليه.\nلكنه كان يقولنا ان اكثر الطلاب مابيفهمون لو اشرح بالانقليزي وأتفهم هالشيء.\nإضافات : طلعت بقريد عادي، والسبب مني لاني قريت التقييم قبل بداية الترم وكانت كلها سلبية فصرت ادخل الكلاس واجلس عالجوال وماركز كثير، بعد وحكمت اني مابتسفيد من الدكتور قبل احضر عنده، بعد الميجر الاول غيرت طريقتي وبديت اجهتد وكان جيد جدا صراحة يتعب عشان يوصل المعلومة ومجتهد بشرحه ومهتم بالطالب حتى بعد التقديم اللي صار بالاختبارات كان يشرح بذمه وحتى لو تأخرنا بالسيلبلس المهم ان الطالب يفهم.\nبالكلاس وورك كان ملك. اخذ افضل كلاست تست واخذ افضل ٣ كويزات من ٥. وزاد كل طالب نقطتين.\nلاتغلط زي غلطتي وتدخل بسلبية لان الدكتور فاهم وبتمشي معه اذا ركزت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475385-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/8", "user": "nvm", "ts": 1497720641000, "tid": 172443, "pn": 8}}]}', 1497720641000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azizlake-math002', 'stk-azizlake', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM192 (نصف الترم أونلاين)\nMath002\n\nالتحضير : أول الكلاس ويمشي لو تأخرت\nطريقة الشرح : يحل أسئلة بس مشكلته ملخبط شوي بعض المرات نسكب سكاشن ما أدري درستها ولا لا زي نظام الغانمي، ومايقدر يوصل الكونسبت كويس للطلاب ( لكن الدكتور ممتاز بالأوفس هاور يشرح لك أزين)\nالكويزات : متوسطة-سهلة لو تذاكر بنفسك تجيب فل بالراحة والدكتور بالكلاس تيست عطانا 3 أسئلة بونس.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: الدكتور مغربي-أمريكي ولهجته واضحة وكثير من الوقت يتكلم عربي خاصة أذا مافهم الطالب.\nإضافات : الدكتور طيب جداً جداً من أطيب الدكاترة والمدرسين اللي قابلتهم بالجامعة وخارجها ويهتم بالطالب كأنه ولده الله يحفظه حتى أتذكر خبصت كثير بالفاينل الشفوي وقعد يتعذر لي يقول الغلط علي انا انك مافهمت… بس لازم تركز معه X2 وإنشاءالله أمورك طيبة انا جبت بالميجر 20\\20 يوم درسني.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525801-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/15", "user": "AzizLake", "ts": 1600623693000, "tid": 172443, "pn": 15}}]}', 1600623693000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alabama_s_alexander-math002', 'stk-alabama_s_alexander', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math002/182\nالتحضير :تحضير يومي٫ يسمح بالليل لحد معين بحكم انه يحضر معظم الأحيان آخر الكلاس٫ ما يسمح ميك اب ابداا\nطريقة الشرح :شرح ممتاز يوصل المعلومة بطريقة جيدة\nالكويزات :يسوي كويزات قليلة٫ سوا معنا ست كويزات بس لدرجة أن الأخير كان آخر خميس قبل تسليم درجات الكلاسوورك الأحد\nالمياجر:شرحه كان ممتاز صراحة وحتى افكار الكلاستيست دقيقة كانت تشابه افكار الميجر\nالفاينلات : ديبارتمينتال ماله دخل\nالقريد النهائي:B\nالصوت:ممتاز و اقدر الخصه ب electrifying\nإضافات :صراحة الدكتور كأخلاق وتعامل كان ممتاز٫ لكن فيه شيء جوهري ما اعجبني على طول السمستر. من أول يوم كان يقولنا\" سوو كويس بالمياجر وبظبطكم بالكويزات\" بالحرف. وبصراحة أنا كنت مهمل بالكويزات ولا أهتم فيها غبت عن اثنين. لكني جبت ١٩ بالأول والثاني ١٨. النهاية جبت كم بالكلاسوورك؟١٢ وربع. بالنهاية الدكتور ما اعتمد على اي شي بالميجر وفقط ركز على الكويزات والكلاستستات و الواجبات الإضافية(اللي انا سويتها كلها إلا آخر واحد) ومع ذلك جبت ١٠ ونص من ١٨٫ لولا بونس الكلاس كان ما صارت ١٢ وربع. فلذلك أنا ما حبيت الإستغفال صراحة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509305-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/6", "user": "Alabama_s_Alexander", "ts": 1556906406000, "tid": 172448, "pn": 6}}]}', 1556906406000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f80-math002', 'stk-f80', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده MATH002 / 182\n\nالتحضير : اغلب الكلاسات كان يحضر بالاخير و تقدر تفلت من الليت احيناً و بالمجمل هو متساهل بالتحضير مره احد الطلاب جا ليت 20 دقيقه ولا غيبه\n\nطريقة الشرح : نوت ممتازه ولاكن ما كنت اذاكر منها كنت معتمد على نوتات مقبل ولاكن شرح الآدمي هذا اقل ما يقال عليه اسطوري , دكتور فاهم الماث مكانه المفروض بكورسات الجبل .\n\nالكويزات : جللللللللللللللللللللللللللللللللللللللللللللللللللللللللللللللد كنا بعد الكويز كل واحد قاعد بكرسيه يشاهق , ولاكن من بدايه الترم و هو يقول ترا الكويزات بتكون صعبه جداً\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+++\n\nالصوت: واضح جداً و لغته ممتازه و يتكلم عربي اغلب الكلاس\n\nإضافات : الدكتور عنده نظام خاص بالبونص و هو انه يعطينا واجبات و على قد ما تسلم منها تاخذ بونص اعلى ( غير البونص العام )\nاعطانا بالترم هذا 6 واجبات سلمت منها 4 , على كل واجب تاخذ 5% زياده على اي شي ناقص عندك , يعني مثلاً لو جايب 95% بكلاس تيست 1 و 75% بكلاس تيست 2 و سلمت 6 واجبات كامله تصير ماخذ 100% بكلاس تيست 1 و 2 , طبعاً كل هذا غير البونص العام اللي كل السكشن بياخذه , و غير كذا اعطانا كويز تحسين و حذف اسوء كويز ز\n\nكان دايم يقول اجتهدو بالميجر و بزبطكم بالكويزات لانها كانت صعبه و فعلاً كنت ما اشد حيلي بالكويزات و حتى الماده بكبرها كنت شبه مهملها لان كان عندي مواد من الجبل ولاكن بالاخير اخذت 17.80 بالكلاس وورك الحمدلله .\n\nاهم شي لاتاخذ كلمته على انك لو ما ذاكرت للكويز بتجيب فل بالكلاس وورك , انت لو تذاكر ما بتقدر تجيب درجه لان الكويز جداً صعب اصلاً ولاكن حاول تسوي اللي تقدر عليه عشان يقدر يساعدك , و الكلاس تيست يكون نسخ لصق من افكار الاولد اقزام يعني سهل .\n\nكويزاتي عنده كانت :\n77.5%\n47.5% > حذفه لي\n50%\n87.5%\n72.5%\n100% > كويز التحسين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509324-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/7", "user": "F80", "ts": 1556938535000, "tid": 172448, "pn": 7}}]}', 1556938535000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hajjar-math002', 'stk-hajjar', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده MATH002 / 192\n\nالتحضير :مهم عنده جدا سواء بالاونلاين او الحضور ويحضر بالعاده بالبدايه ولا يقبل الميك اب\n\nطريقة الشرح :جميلة جدا صح اني عانيت باول شابتر الى ما تعودت عليه لكن يوصل المعلومة بشكل دقيق ويستخدم ايباد للحل ويعرضه عالبورد وبعض الطلاب ما كانت تناسبهم هذي الطريقة لكن اشوفها جيده\n\nالكويزات : هنا عاد نجي كويزاته الصراحه جللد اذكر اول كويز كان افرجنا 45% كويزاته غالبا سؤالين وسط وسؤالين صعبه وغالبا يحيبهم من الاولد اقزام الصعبه حتى لما رحنا اونلاين فيه كم كويز كان جلد لكن كلمناه وسهلهم\n\nالقريد النهائي: B+/A\n\nالصوت:واضح ولهجته الانقليزيه ممتازه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525162-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/8", "user": "hajjar", "ts": 1598592804000, "tid": 172448, "pn": 8}}]}', 1598592804000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tweiti-math002', 'stk-tweiti', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math002\n202-online\nالتحضير: على تيمز و لازم تكون فاك الكام\nطريقة الشرح : عنده نوتاته و هي جيدة لكن مهي ممتازة اشوف فيها امثلة زيادة عن اللزوم و بعض الامثلة حلها طويييل و اشوف ذا يختبر صبرك مو فهمك.\nميزة النوتات انها مجمعة في الون نوت و مقسمة تقسيم رهيب الشرح اسطوري و لكن احس النوتات لو يقلل الامثله يكون ممتاز و البعض عاجباه ممكن ما زبطت معاي لكن الشرح رهيييب لكن لما تقدمت الاختبارات صار مره سريع و يدوب تلحق 😂\nالكويزات: ماث 002 سهل ما يمديه يحط تريكات و الكويزات كانت سهله إلى متوسطة لكن لازم تذاكر و تكون مركز مو جاي للكويز فاصل نوم زي كوزات رمضان و المحاضرة 7 😞\nالقريد النهائي: S 🚬\nاضافات:\nالدكتور اخلااااااااااااااااااااااااااااااااااااااااااااق خلك معه محترم و صادق و تفاهم معي ب اي شي يصير معك او يمنعك من الحضور و يزبطك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529896-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/12", "user": "Tweiti", "ts": 1620404242000, "tid": 172448, "pn": 12}}]}', 1620404242000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad.ah-math002', 'stk-ahmad.ah', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 -163\n\nالتحضير : بداية الكلاس “يوميا”\n\nطريقة الشرح : يستخدم السلايدات حقته ، وهاذي ارهب شي عنده لانها تغطي لك الدرس بشكل كامل ومعها اسئلة براكتس تكون من عند الدكتور نفسه\n\nالكويزات : من نفس السلايدات ، تقريبا الكويز بشكل عام متوسط ويكون تقريبا ٤ اسئلة ، اكثر من مرة جاب لنا من اسئلة البراكتس اللي هو يسويها\n\nالقريد النهائي: اذا نزل لك الماث عند هالدكتور ارتاح وتطمن\n\nالصوت: واضح جداً\n\nإضافات :\n\n- - الدكتور متعاون جدا من ناحية التصحيح ، اللي يعجبني فيه ان يقرا الورقة حقت كاملة بالتفصيل يعني لو حليت سوال وممكن في نص الحل نسيت اشارة ولكن طريقة الحل وفهمك للفكرة مضبوط ممكن يعطيك على السوال ٣ او ٤ من ٥\n\n-- اسئلة البراكتس اللي موجودة في السلايدات مهمة مهمة بشكل كبير ، تقريبا تجي الافكار فيها قوية واذا حليت كل اسئلة البراكتس لكل درس ورحت للدكتور للمكتب عشان تتاكد من الحل \" لانه نادر مايحط اجاباتها ، لكن عشان الصيفي هالمرة ضغط نزل الاجابات في السلايدات \"\nاضمن لك انك راح تبدع في المياجر و الكويزات.\n-- طبعا من اسوء الاشياء اللي ممكن تسويها عنده انك تمسك جوالك ، الحركة ذي تزعله كثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479226-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/2", "user": "Ahmad.AH", "ts": 1503557316000, "tid": 176966, "pn": 2}}]}', 1503557316000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-d.zh-math002', 'stk-d.zh', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 002 -163\n\nالتحضير : يوميا بعد مايعطي فكرة الدرس وايش اللي بناخذه ( وأحيانا ) يسامح اللي جايين متأخر\n\nطريقة الشرح : عن طريق السلايدات لكامل الكورس وهي جدا ممتازة وتغطي كامل الافكار بالاضافة الى البراكتس نهاية كل درس وهي عبارة عن اولد اكزام وجدا ممتازة وفيها افكار تتكرر بالمياجر كثير انصحك تحلها .\n\nالكويزات : من متوسطة الى صعبة نوعا ما بس كلها من افكار السلايدات والبراااااكتس بمجرد فهمك للدرس وحلك للبراكتس تضمن الكويز بشكل كبير .\n\nالقريد النهائي : A+++ الدكتور محمد من افضل دكاترة ( الاوريا ) هنيئا للي راح يدرس معه\n\nالصوت : واضح جداً\n\nالمياجر : كومن\n\nالفاينلات : كومن ، والدكتور محمد سوا لنا ريفيو نهاية الكورس شامل جميع المنهج للفاينل من اولد اكزامز للفاينلات السابقه وفيها افكار تجي بالفاينل\n\nإضافات :\nـــ الدكتور مرح جدا جدا بالكلاس ويحب يسوي جو فكاهي وراح يونسك اثناء الكلاس ، وجدا مهتم بالطالب .\nـــ انصحك انك تحرص على انك تروح له بالاوفيس اور راح ياخذ انطباع جيد عنك و ممكن يزيدك بالكلاس وورك على حرصك .\n\nوبالتوفيق لكم ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479274-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/3", "user": "D.Zh", "ts": 1503596466000, "tid": 176966, "pn": 3}}]}', 1503596466000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ashen_one-math002', 'stk-ashen_one', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math002 163\nالتحضير:يوميا وشديد جدا فيه\nالشرح:من السلايدات و ممتازة جدا و واضحة وباخر كل درس يكون فيه practice problems افكارها مهمة وتهيئك لكويزاته والكلاس تست لان يجيب منها فاول ما تذاكر تاخذ نوتس من السلايدات وعلى اسئلة السلابس من الكتاب بعدها البراكتس واولد اقزام وكذا تكون مستعد للمياجر\nالمياجر:كومون\nالفاينل:كومون\nاضافات:دكتور حبيب ويهتم للطالب وفهمه وما يردك بالاوفس والوضع ضحك بالكلاس ما تقدر تمسك نفسك\nاذا نزلت عنده اعرف انك محظوظ\nاربع قارات وست جامعات(بتسمعها كثير منه)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479302-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/4", "user": "Ashen_one", "ts": 1503626552000, "tid": 176966, "pn": 4}}]}', 1503626552000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-math002', 'stk-to_be_engineer', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Math 002 (163\nالتحضير : اول خمس دقايق، اذا شاف واحد تأخر كثير يحطه ليت.\nطريقة الشرح **:**سلايدات عظيمه هو يسويها واللي يزيد عظمتها شرحه السلس… يحط اسئلة من عنده تحصل فيها اكثر من فكرة تفتح مخك… كل كلاس يعطينا سؤال او سؤالين نحلها ويصير فيها نقاش مليئ بالاكشن 😆… نهاية الشرح يحط تقريبا اربع اسئلة اذا حليتها هذا دليل انك متمكن من الدرس، الحل ما كان موجود لانه يبيك تجيه في الاوفس اور عشان يحس انك مهتم (هذا اللي يصير بالعادة لكن بالصيفي حط الحلول لضيق الوقت).\nالكويزات : متوسطة،غالبا تجي مشابه للاسئلة الاضافية اللي في سلايداته… بعض الطلاب كان يشوفها صعبه لانه ما يحل الاسئلة.\nالمياجر: كومن.\nالفاينلات : كومن.\nالقريد النهائي: A+\nالصوت: اكسنت لبناني لكن واضح.\nإضافات : الدكتور متكمن ويعشق الماث بكل ما تعنيه الكلمة… كان يستمتع بالشرح وبالتالي انت راح تستمتع… يقط نكات ويقلب جو الكلاس… دايم افرج كلاساته فوق الافرج العام… انا الان خلصت ماث 102 واقولها هذا افضل دكتور درسني ماث وما اتوقع راح ادرس عند واحد افضل منه .\n\nاذا حطوك عنده احمد ربك كثيررر واجتهد معه لان جهدك ما راح يروح عالفاضي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492695-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/7", "user": "To_Be_Engineer", "ts": 1526675112000, "tid": 176966, "pn": 7}}]}', 1526675112000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed3005-math002', 'stk-mohammed3005', 'MATH 002', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده Math 002 || Term 202 أونلاين.\n\nالتحضير: يعتبر شديد، كان يفتح الغرفه حقت المحاضرة قبلها ب5 دقائق فأذا كانت حصتك مثلاً ساعه 11:00ص وجيت 11:01 راح يعتبرك Late او متأخر.\n\nطريقة الشرح: عباره عن سلايدات مكتوبه مسبقاً بالكمبيوتر، يشرح لك الفكره حقت الدرس منها بشكل بسيط، ثم يحل لك أول سؤال، بعدين ببقيه الاسأله يعرض السؤال ويطلب من الطلاب يشاركوا ويحله معاهم.\n\nالكويزات: مستوى الأفرج حق الكويزات بنهايه الترم كان 55.64‎%‎ وبعدين زاد طلاب شعبتنا بونصات لين ماصار 75 أتوقع تقريباً ، وهناك إيجابية راح اذكرها عن كويزاته.\nالقريد النهائي لسا ماصدر حتى الآن.\nالصوت : واضح جداً …\n\n* معلومات مهمه :\n- من الجميل بهذا الدكتور، أنه ماتحصل بكويزاته 0 لأنه لمجرد كتابه الأسم ورقم الشعبه والرقم الجامعي راح يعطيك عليها 6 درجات …\n- ايضاً جميل بالدكتور أنه صدره وسيع وشريح، مافيه اي مشاكل معاه من الناحية الاخلاقية.\n- أذا صرت عنده، أهتم بالمشاركه والذهاب للأوفس لانه يحفظ أسماء الطلاب المشاركين ويزيدهم بونصات بنهايه السنه.\n- الدكتور يتكلم طول الكلاس بالأنجليزي بإستثناء كم كلمه يقولها عربي، ومايقبل الطلاب يتكلموا معه عربي.\n- عنده قناه باليوتيوب شرح فيها دروس ماث 001 وماث 002 .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529692-math002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/13", "user": "Mohammed3005", "ts": 1619429898000, "tid": 176966, "pn": 13}}]}', 1619429898000, 1794835934, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
